int failures = 0;

void check(bool condition, const QString &what);

void testSystemdUserServiceUnitFromCgroup()
{
    const QByteArray userService =
        "0::/user.slice/user-1001.slice/user@1001.service/app.slice/"
        "forkmesh-source.service\n";
    check(forkmesh::ui::systemdUserServiceUnitFromCgroup(userService) ==
              QStringLiteral("forkmesh-source.service"),
          QStringLiteral("a systemd user-service cgroup identifies the "
                         "supervising desktop unit"));

    const QByteArray systemService =
        "0::/system.slice/forkmesh-source.service\n";
    check(forkmesh::ui::systemdUserServiceUnitFromCgroup(systemService).isEmpty(),
          QStringLiteral("a system service is never stopped through the user "
                         "service manager"));

    check(forkmesh::ui::systemdUserServiceCloseArguments(
              QStringLiteral("forkmesh-source.service"), false) ==
              QStringList({QStringLiteral("--user"), QStringLiteral("stop"),
                           QStringLiteral("--no-block"),
                           QStringLiteral("forkmesh-source.service")}),
          QStringLiteral("an interactive close stops the supervising unit"));
    check(forkmesh::ui::systemdUserServiceCloseArguments(
              QStringLiteral("forkmesh-source.service"), true) ==
              QStringList({QStringLiteral("--user"), QStringLiteral("restart"),
                           QStringLiteral("--no-block"),
                           QStringLiteral("forkmesh-source.service")}),
          QStringLiteral("rebuild & restart restarts the unit instead of "
                         "stopping it and the relaunched child"));
    check(forkmesh::ui::systemdUserServiceCloseArguments(QString(), true)
              .isEmpty(),
          QStringLiteral("no unit, no systemctl call"));

    const QByteArray userScope =
        "0::/user.slice/user-1001.slice/user@1001.service/app.slice/"
        "app-org.kde.konsole.scope\n";
    check(forkmesh::ui::systemdUserServiceUnitFromCgroup(userScope).isEmpty(),
          QStringLiteral("ordinary user-session scopes do not opt into "
                         "service shutdown"));

    const QString guardUnit = QStringLiteral("forkmesh-source.service");
    check(forkmesh::ui::closeHoldsSourceGuard(guardUnit, false, false),
          QStringLiteral("a close holds the source guard by default"));
    check(!forkmesh::ui::closeHoldsSourceGuard(guardUnit, false, true),
          QStringLiteral("reopen-after-close leaves the guard free"));
    check(!forkmesh::ui::closeHoldsSourceGuard(guardUnit, true, false),
          QStringLiteral("rebuild & restart never holds the guard"));
    check(!forkmesh::ui::closeHoldsSourceGuard(
              QStringLiteral("forkmesh-other.service"), false, false),
          QStringLiteral("another unit's close does not hold the flagship"));

    QTemporaryDir holdDir;
    const QString holdPath =
        holdDir.path() + QStringLiteral("/publisher/source-hold.json");
    check(forkmesh::ui::writeDesktopCloseHold(holdPath, 1000),
          QStringLiteral("the close hold is written"));
    QFile holdFile(holdPath);
    holdFile.open(QIODevice::ReadOnly);
    const QJsonObject hold = QJsonDocument::fromJson(holdFile.readAll()).object();
    holdFile.close();
    check(hold.value(QStringLiteral("until")).toDouble() >
                  1000 + 50.0 * 365 * 24 * 3600 &&
              hold.value(QStringLiteral("setBy")).toString() ==
                  QStringLiteral("desktop"),
          QStringLiteral("the close hold lasts until the desktop starts again"));
    check(forkmesh::ui::releaseDesktopCloseHold(holdPath) &&
              !QFile::exists(holdPath),
          QStringLiteral("the next start releases the desktop's hold"));

    QFile manual(holdPath);
    manual.open(QIODevice::WriteOnly);
    manual.write("{\"until\": 99999999999, \"reason\": \"rebuilding\"}");
    manual.close();
    check(!forkmesh::ui::releaseDesktopCloseHold(holdPath) &&
              QFile::exists(holdPath),
          QStringLiteral("a start leaves a hand-set hold alone"));
}

