class StyleChangeCounter final : public QObject
{
public:
    QHash<QObject *, int> counts;

protected:
    bool eventFilter(QObject *watched, QEvent *event) override
    {
        if (event->type() == QEvent::StyleChange && watched->isWidgetType())
            ++counts[watched];
        return false;
    }
};

void checkSettingsOutline(MainWindow &window, bool next)
{
    QSettings settings;
    const QVariant themeBefore = settings.value(QStringLiteral("app/theme"));
    if (next) {
        settings.setValue(QStringLiteral("app/design"), QStringLiteral("next"));
        MainWindow::applyTheme();
    }
    window.testEnableSessionStartBypass(true);
    window.testSetSetupInputs(QStringLiteral("qa-tester"), QString());
    window.testStartSession();
    window.resize(1440, 900);
    window.show();
    window.testShowSettingsSection();
    settleAnimations();

    auto *sections =
        window.findChild<SettingsSectionsView *>(QStringLiteral("settingsSections"));
    auto *nav = window.findChild<QListWidget *>(QStringLiteral("settingsNav"));
    check(sections && nav && nav->count() == sections->count(),
          QStringLiteral("every Settings section has its entry in the list on the left"));
    if (!sections || !nav)
        return;
    sections->setCollapsedTitles({});
    settleAnimations();

    QStringList unlisted;
    QStringList unlit;
    for (int i = 0; i < sections->count(); ++i) {
        if (sections->isSectionHidden(i))
            continue;
        sections->setCurrentIndex(i);
        settleAnimations(250);
        QWidget *body = sections->widget(i);
        const QString section = sections->tabText(i);
        if (nav->item(i)->text() != section || nav->currentRow() != i)
            unlisted << QStringLiteral("%1 (list entry)").arg(section);
        auto *lit = qobject_cast<QLabel *>(sections->litHeading());
        if (!lit || !lit->property("settingsLit").toBool() || !lit->isVisibleTo(&window))
            unlit << section;
        if (!body)
            continue;
        const QStringList listed = sections->subSectionTitles(i);
        QStringList headings;
        int cards = 0;
        const QList<QWidget *> children =
            body->findChildren<QWidget *>(QString(), Qt::FindDirectChildrenOnly);
        for (QWidget *card : children) {
            if (!card->property("sectionCard").toBool() || !card->isVisibleTo(body))
                continue;
            ++cards;
            QString heading;
            for (QLabel *label : card->findChildren<QLabel *>(QStringLiteral("sectionLabel"))) {
                if (label->isVisibleTo(card)) {
                    heading = label->text();
                    break;
                }
            }
            if (heading.isEmpty()) {
                QString first;
                for (QWidget *inner : card->findChildren<QWidget *>()) {
                    if (auto *button = qobject_cast<QAbstractButton *>(inner);
                        button && !button->text().isEmpty() && inner->isVisibleTo(card)) {
                        first = button->text();
                        break;
                    }
                    if (auto *label = qobject_cast<QLabel *>(inner);
                        label && !label->text().isEmpty() && inner->isVisibleTo(card)) {
                        first = label->text().left(40);
                        break;
                    }
                }
                unlisted << QStringLiteral("%1 > card without a heading (%2)").arg(section, first);
                continue;
            }
            headings << heading;
        }
        if (cards >= 2 && listed.size() != headings.size())
            unlisted << QStringLiteral("%1 > list [%2] page [%3]")
                            .arg(section, listed.join(QStringLiteral(", ")),
                                 headings.join(QStringLiteral(", ")));
    }
    for (const QString &line : std::as_const(unlisted))
        std::fprintf(stderr, "  settings outline: %s\n", qPrintable(line));
    check(unlisted.isEmpty(),
          QStringLiteral("every group on the Settings page is listed on the left, in "
                         "the same order and under the same heading"));
    for (const QString &line : std::as_const(unlit))
        std::fprintf(stderr, "  settings heading not lit: %s\n", qPrintable(line));
    check(unlit.isEmpty(),
          QStringLiteral("jumping to a section lights its heading on the page, as its "
                         "entry is lit in the list"));

    const QString shots = qEnvironmentVariable("FORKMESH_SETTINGS_SHOT");
    int generalIndex = -1;
    for (int i = 0; i < sections->count(); ++i) {
        if (sections->tabText(i) == QLatin1String("General"))
            generalIndex = i;
    }
    sections->setCurrentIndex(generalIndex);
    settleAnimations();
    if (!shots.isEmpty())
        window.grab().save(shots + QStringLiteral("-general.png"));

    auto *localHalloween =
        window.findChild<QCheckBox *>(QStringLiteral("halloweenLocalCheck"));
    sections->setSearchText(QStringLiteral("halloween"));
    settleAnimations();
    const QList<QWidget *> hits = sections->searchHits();
    check(sections->visibleSectionTitles().contains(QStringLiteral("General")) &&
              localHalloween && hits.contains(localHalloween),
          QStringLiteral("searching Settings for halloween finds the Halloween theme "
                         "switch in General"));
    if (!shots.isEmpty()) {
        sections->nextSearchHit();
        settleAnimations();
        window.grab().save(shots + QStringLiteral("-search.png"));
    }
    sections->setSearchText(QString());
    settleAnimations();

    auto *themeCombo = window.findChild<QComboBox *>(QStringLiteral("appThemeCombo"));
    if (localHalloween && themeCombo) {
        themeCombo->setCurrentIndex(themeCombo->findData(QStringLiteral("light")));
        settleAnimations(100);
        localHalloween->setChecked(true);
        settleAnimations(100);
        const bool on = settings.value(QStringLiteral("app/theme")).toString() ==
                        QLatin1String("halloween");
        localHalloween->setChecked(false);
        settleAnimations(100);
        check(on && settings.value(QStringLiteral("app/theme")).toString() ==
                        QLatin1String("light") &&
                  !localHalloween->isChecked(),
              QStringLiteral("the Halloween switch in Settings turns the theme on and "
                             "back to the one chosen before"));
        themeCombo->setCurrentIndex(themeCombo->findData(QStringLiteral("halloween")));
        settleAnimations(100);
        check(localHalloween->isChecked(),
              QStringLiteral("picking Halloween in the theme list ticks the Halloween switch"));
    }
    auto *adminBox = window.findChild<QWidget *>(QStringLiteral("seasonAdminBox"));
    check(adminBox && !adminBox->isVisibleTo(&window),
          QStringLiteral("the switch for everyone stays hidden from an account that "
                         "cannot manage it"));
    if (themeBefore.isValid())
        settings.setValue(QStringLiteral("app/theme"), themeBefore);
    else
        settings.remove(QStringLiteral("app/theme"));
    if (next)
        settings.remove(QStringLiteral("app/design"));
}

void checkThemeSwitchRepolish(MainWindow &window)
{
    window.testEnableSessionStartBypass(true);
    window.testSetSetupInputs(QStringLiteral("qa-tester"), QString());
    window.testStartSession();
    window.resize(1440, 900);
    window.show();
    window.testShowSettingsSection();
    window.testShowChatSection();
    window.testShowLogSection();
    window.testShowMarketSection();
    window.testShowLedgerSection();
    window.testShowHostsSection();
    window.testShowUsersSection();
    window.testShowNodesSection();
    window.testShowHomeSection();
    settleAnimations();

    QSettings settings;
    const QVariant themeBefore = settings.value(QStringLiteral("app/theme"));
    auto switchTo = [&](const QString &theme, int *maxPerWidget, int *total) {
        settings.setValue(QStringLiteral("app/theme"), theme);
        StyleChangeCounter counter;
        qApp->installEventFilter(&counter);
        QElapsedTimer timer;
        timer.start();
        MainWindow::applyTheme();
        const qint64 elapsed = timer.elapsed();
        qApp->removeEventFilter(&counter);
        *maxPerWidget = 0;
        *total = 0;
        for (const int count : std::as_const(counter.counts)) {
            *maxPerWidget = qMax(*maxPerWidget, count);
            *total += count;
        }
        qInfo().noquote() << QStringLiteral(
                                 "theme switch to %1: %2 ms, %3 widgets, %4 "
                                 "style changes, at most %5 on one widget")
                                 .arg(theme)
                                 .arg(elapsed)
                                 .arg(QApplication::allWidgets().size())
                                 .arg(*total)
                                 .arg(*maxPerWidget);
        settleAnimations();
    };

    int maxPerWidget = 0;
    int total = 0;
    switchTo(QStringLiteral("dark"), &maxPerWidget, &total);
    switchTo(QStringLiteral("light"), &maxPerWidget, &total);
    check(Theme::color(Theme::Role::Bg).lightness() > 128,
          QStringLiteral("switching to the light theme recolours the app"));
    check(total <= QApplication::allWidgets().size() * 3,
          QStringLiteral("a theme switch restyles each widget about twice, "
                         "not once per ancestor"));
    const QString sheet = qApp->styleSheet();
    switchTo(QStringLiteral("light"), &maxPerWidget, &total);
    check(qApp->styleSheet() == sheet &&
              total < QApplication::allWidgets().size() / 4,
          QStringLiteral("applying the theme already shown leaves the "
                         "application style sheet alone"));
    switchTo(QStringLiteral("dark"), &maxPerWidget, &total);
    check(Theme::color(Theme::Role::Bg).lightness() < 128 &&
              !qApp->styleSheet().isEmpty(),
          QStringLiteral("switching back to dark restores a dark style sheet"));

    if (themeBefore.isValid())
        settings.setValue(QStringLiteral("app/theme"), themeBefore);
    else
        settings.remove(QStringLiteral("app/theme"));
    MainWindow::applyTheme();
    settleAnimations();
}

void checkAppViewModes(MainWindow &window)
{
    using forkmesh::ui::AppViewMode;
    QTemporaryDir tree;
    check(tree.isValid() &&
              QProcess::execute(QStringLiteral("git"),
                                {QStringLiteral("-C"), tree.path(),
                                 QStringLiteral("init"), QStringLiteral("-q")}) == 0,
          QStringLiteral("view-mode fixture repository initialised"));

    window.testEnableSessionStartBypass(true);
    window.testSetSetupInputs(QStringLiteral("qa-tester"), QString());
    window.testStartSession();
    window.resize(1440, 900);
    window.show();
    window.testSetAppViewMode(AppViewMode::Standard);
    QApplication::processEvents();

    QPushButton *button = window.testViewModeButton();
    // The setup page carries its own, now hidden, chrome close button.
    QPushButton *closeButton = nullptr;
    for (QPushButton *candidate : window.findChildren<QPushButton *>(
             QStringLiteral("windowChromeCloseButton"))) {
        if (candidate->isVisible())
            closeButton = candidate;
    }
    const QRect buttonRect =
        button ? QRect(button->mapTo(&window, QPoint(0, 0)), button->size()) : QRect();
    const QRect closeRect =
        closeButton ? QRect(closeButton->mapTo(&window, QPoint(0, 0)),
                            closeButton->size())
                    : QRect();
    check(button && button->isVisible() && closeButton &&
              buttonRect.center().x() > window.width() * 3 / 4 &&
              buttonRect.right() < closeRect.left() &&
              qAbs(buttonRect.center().y() - closeRect.center().y()) <= 2,
          QStringLiteral("the view switcher sits in the top-right chrome, left "
                         "of the window controls"));
    check(window.testAppNavigationRail() && window.testAppNavigationRail()->isVisible() &&
              window.testAppStatusArea() && window.testAppStatusArea()->isVisible(),
          QStringLiteral("Standard view shows the rail and the status strip"));

    window.testSetAppViewMode(AppViewMode::Focus);
    QApplication::processEvents();
    check(window.testAppViewMode() == AppViewMode::Focus &&
              !window.testAppNavigationRail()->isVisible() &&
              !window.testAppStatusArea()->isVisible() && button->isVisible(),
          QStringLiteral("Focus view hides the rail and status strip but keeps "
                         "the switcher"));
    check(QSettings().value(QStringLiteral("ui/viewMode")).toString() ==
              QStringLiteral("focus"),
          QStringLiteral("the chosen view is saved by name"));

    const int repositoryIndex = window.testAddLocalRepository(
        QStringLiteral("forkmesh"), QStringLiteral("view-mode-probe"), tree.path());
    check(repositoryIndex >= 0 && window.testOpenRepository(repositoryIndex),
          QStringLiteral("the view-mode fixture repository opens"));
    QApplication::processEvents();
    window.testSetAppViewMode(AppViewMode::Workspace);
    QApplication::processEvents();
    QSplitter *split = window.testAgentWorkspaceSplit();
    QWidget *dock = window.testWorkspaceTerminalDock();
    check(split && dock && split->count() == 3 && split->widget(2) == dock &&
              dock->isVisible() && dock->width() >= 240 &&
              window.testWorkspaceTerminal() &&
              dock->isAncestorOf(window.testWorkspaceTerminal()),
          QStringLiteral("Workspace view opens Agents with a terminal pane beside "
                         "the transcript"));
    check(!window.testAppNavigationRail()->isVisible() &&
              !window.testAppStatusArea()->isVisible(),
          QStringLiteral("Workspace view also gives the rail and status strip back"));

    window.testCycleAppViewMode();
    QApplication::processEvents();
    check(window.testAppViewMode() == AppViewMode::Standard && !dock->isVisible() &&
              window.testAppNavigationRail()->isVisible() &&
              window.testAppStatusArea()->isVisible(),
          QStringLiteral("cycling past Workspace restores the Standard shell"));
}

void checkAgentToolEfficiency(MainWindow &window)
{
    // The Agents page is a repo-detail tab, so a repository has to be open
    // before it can be built. Seed a throwaway one and use it as the agent's
    // worktree too, so file-size baselines resolve against real files.
    QTemporaryDir tree;
    const bool gitReady =
        tree.isValid() &&
        QProcess::execute(QStringLiteral("git"),
                          {QStringLiteral("-C"), tree.path(), QStringLiteral("init"),
                           QStringLiteral("-q"), QStringLiteral("-b"),
                           QStringLiteral("main")}) == 0;
    {
        QFile fixture(QDir(tree.path()).filePath(QStringLiteral("notes.txt")));
        check(gitReady && fixture.open(QIODevice::WriteOnly) &&
                  fixture.write(QByteArray(40000, 'x')) == 40000,
              QStringLiteral("efficiency fixture repository written"));
    }
    for (const QStringList &args :
         {QStringList{QStringLiteral("config"), QStringLiteral("user.email"),
                      QStringLiteral("qa@example.invalid")},
          QStringList{QStringLiteral("config"), QStringLiteral("user.name"),
                      QStringLiteral("QA")},
          QStringList{QStringLiteral("add"), QStringLiteral("notes.txt")},
          QStringList{QStringLiteral("commit"), QStringLiteral("-qm"),
                      QStringLiteral("seed")}})
        QProcess::execute(QStringLiteral("git"),
                          QStringList{QStringLiteral("-C"), tree.path()} + args);

    window.testEnableSessionStartBypass(true);
    window.testSetSetupInputs(QStringLiteral("qa-tester"), QString());
    window.testStartSession();
    window.resize(1440, 900);
    window.show();
    const int repositoryIndex = window.testAddLocalRepository(
        QStringLiteral("forkmesh"), QStringLiteral("efficiency-probe"), tree.path());
    check(repositoryIndex >= 0 && window.testOpenRepository(repositoryIndex),
          QStringLiteral("the efficiency fixture repository opens"));
    QApplication::processEvents();
    window.testOpenAgentsOverview();
    QApplication::processEvents();

    QStackedWidget *stack = window.testAgentPageStack();
    AgentToolEfficiencyBoard *board = window.testAgentEfficiencyBoard();
    AgentToolEfficiencyLedger *ledger = window.testAgentToolLedger();
    AgentToolImprovementLog *improvements = window.testAgentToolImprovements();
    auto *efficiencyButton =
        window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyButton"));
    auto *deleteSelected =
        window.findChild<QPushButton *>(QStringLiteral("agentDeleteSelectedButton"));
    auto *backButton =
        window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyBack"));
    QWidget *actionBar = window.findChild<QWidget *>(QStringLiteral("agentsActionBar"));
    const QList<QWidget *> barOrder =
        actionBar ? actionBar->findChildren<QWidget *>(QString(),
                                                       Qt::FindDirectChildrenOnly)
                  : QList<QWidget *>();
    const int deleteIndex = deleteSelected ? int(barOrder.indexOf(deleteSelected)) : -1;
    const int efficiencyIndex =
        efficiencyButton ? int(barOrder.indexOf(efficiencyButton)) : -2;
    const bool watchInActionBar =
        window.findChild<QPushButton *>(QStringLiteral("agentVisualButton")) != nullptr;
    check(stack && stack->count() == 4 && stack->currentIndex() == 0 &&
              !window.findChild<QTabBar *>(QStringLiteral("agentPageTabs")) &&
              efficiencyButton && efficiencyButton->isVisibleTo(actionBar) &&
              efficiencyButton->text() == QStringLiteral("Tool efficiency") &&
              deleteIndex >= 0 && efficiencyIndex == deleteIndex + 1 &&
              !watchInActionBar && backButton,
          QStringLiteral("Tool efficiency is a button in the run of page buttons after "
                         "Delete selected, not a tab, and Watch lives in the rail "
                         "(stack=%1 delete=%2 watch-in-bar=%3 efficiency=%4)")
              .arg(stack ? stack->count() : -1)
              .arg(deleteIndex)
              .arg(watchInActionBar)
              .arg(efficiencyIndex));
    check(board != nullptr,
          QStringLiteral("the Tool efficiency tab hosts the efficiency board"));
    check(ledger != nullptr,
          QStringLiteral("the agent store owns a tool efficiency ledger"));
    if (!stack || !efficiencyButton || !backButton || !board || !ledger ||
        !improvements)
        return;
    ledger->clear();
    improvements->clear();

    QWidget *agentsPage = window.findChild<QWidget *>(QStringLiteral("agentsPage"));
    QWidget *listPane = window.findChild<QWidget *>(QStringLiteral("agentsListPane"));
    const int listBottomInPage =
        listPane && agentsPage
            ? listPane->mapTo(agentsPage, QPoint(0, listPane->height())).y()
            : -1;
    // With no transcript pane open the page itself reserves the docked
    // composer's band (adhoc #201), so the list must reach the bottom of the
    // page's content area, whatever that band currently is.
    const int pageContentBottom =
        agentsPage && agentsPage->layout()
            ? agentsPage->height() - agentsPage->layout()->contentsMargins().bottom()
            : -1;
    check(agentsPage && listPane && listPane->isVisibleTo(&window) &&
              listBottomInPage >= pageContentBottom - 1,
          QStringLiteral("the Sessions tab still runs the list pane to the page "
                         "bottom (list=%1 content=%2 page=%3)")
              .arg(listBottomInPage)
              .arg(pageContentBottom)
              .arg(agentsPage ? agentsPage->height() : -1));

    efficiencyButton->click();
    QApplication::processEvents();
    check(stack->currentIndex() == 1 && board->isVisibleTo(&window) && listPane &&
              !listPane->isVisibleTo(&window) && board->improvementRowCount() == 0 &&
              board->cardCount() == agentToolFamilies().size() &&
              board->observedCardCount() == 0 &&
              board->tileValue(QStringLiteral("Coverage")) ==
                  QStringLiteral("0 / %1").arg(agentToolFamilies().size()) &&
              board->contentHeight() > 0 && board->minimumHeight() == board->contentHeight(),
          QStringLiteral("the board lists every catalog family before any call"));

    // "Send to agent" sits between Copy improvements and Open log; with
    // nothing recorded there is nothing to launch on, so a click stays put.
    auto *copyImprovementsButton = window.findChild<QPushButton *>(
        QStringLiteral("agentEfficiencyCopyImprovements"));
    auto *sendToAgentButton = window.findChild<QPushButton *>(
        QStringLiteral("agentEfficiencySendToAgent"));
    auto *openLogButton =
        window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyOpenLog"));
    QLayout *efficiencyHeader =
        copyImprovementsButton && copyImprovementsButton->parentWidget()
            ? copyImprovementsButton->parentWidget()->layout()
            : nullptr;
    const int copyIndex = efficiencyHeader && copyImprovementsButton
                              ? efficiencyHeader->indexOf(copyImprovementsButton)
                              : -1;
    const int sendIndex = efficiencyHeader && sendToAgentButton
                              ? efficiencyHeader->indexOf(sendToAgentButton)
                              : -3;
    const int openLogIndex = efficiencyHeader && openLogButton
                                 ? efficiencyHeader->indexOf(openLogButton)
                                 : -5;
    check(sendToAgentButton && sendToAgentButton->isVisibleTo(&window) &&
              sendToAgentButton->text() == QStringLiteral("Send to agent") &&
              copyIndex >= 0 && sendIndex == copyIndex + 1 &&
              openLogIndex == sendIndex + 1,
          QStringLiteral("Send to agent sits between Copy improvements and Open "
                         "log (copy=%1 send=%2 log=%3)")
              .arg(copyIndex)
              .arg(sendIndex)
              .arg(openLogIndex));
    if (sendToAgentButton) {
        sendToAgentButton->click();
        QApplication::processEvents();
    }
    check(window.testAgentToolImprovementsFixPrompt().isEmpty() &&
              stack->currentIndex() == 1 && board->isVisibleTo(&window),
          QStringLiteral("with no signals recorded there is nothing to send and "
                         "the click stays on the board"));

    AgentSession session;
    session.id = 9101;
    session.name = QStringLiteral("efficiency probe");
    session.provider = QStringLiteral("claude-code");
    session.model = QStringLiteral("claude-sonnet-5");
    session.status = AgentStatus::Running;
    session.createdAtMs = QDateTime::currentMSecsSinceEpoch();
    window.testAddAgentSession(session);
    window.testSetStreamWorktree(session.id, tree.path());

    auto block = [](const QJsonObject &inner, const QString &role) {
        return QJsonObject{
            {QStringLiteral("type"), role},
            {QStringLiteral("message"),
             QJsonObject{{QStringLiteral("role"), role},
                         {QStringLiteral("content"), QJsonArray{inner}}}}};
    };
    window.testApplyTranscriptEvent(
        session.id,
        block(QJsonObject{{QStringLiteral("type"), QStringLiteral("tool_use")},
                          {QStringLiteral("id"), QStringLiteral("toolu_eff_1")},
                          {QStringLiteral("name"), QStringLiteral("Read")},
                          {QStringLiteral("input"),
                           QJsonObject{{QStringLiteral("file_path"),
                                        QStringLiteral("notes.txt")},
                                       {QStringLiteral("limit"), 3}}}},
              QStringLiteral("assistant")));
    check(ledger->stats(QStringLiteral("read")).inFlight == 1 &&
              ledger->stats(QStringLiteral("read")).calls == 1,
          QStringLiteral("a streamed tool_use opens an in-flight read"));
    window.testApplyTranscriptEvent(
        session.id,
        block(QJsonObject{{QStringLiteral("type"), QStringLiteral("tool_result")},
                          {QStringLiteral("tool_use_id"), QStringLiteral("toolu_eff_1")},
                          {QStringLiteral("content"), QStringLiteral("1\txxx\n2\txxx\n")},
                          {QStringLiteral("is_error"), false}},
              QStringLiteral("user")));
    const AgentToolFamilyStats read = ledger->stats(QStringLiteral("read"));
    check(read.inFlight == 0 && read.measuredCalls == 1 && read.savedTokens > 9000 &&
              read.savedUsd > 0.0,
          QStringLiteral("the tool_result measures the whole-file baseline and the saving"));

    window.testRefreshAgentEfficiencyBoard();
    QApplication::processEvents();
    check(board->observedCardCount() == 1 &&
              board->cardHeadline(QStringLiteral("read")).contains(QStringLiteral("tokens saved")) &&
              board->tileValue(QStringLiteral("Coverage")).startsWith(QStringLiteral("1 /")) &&
              board->tileValue(QStringLiteral("Tool calls")) == QStringLiteral("1") &&
              !board->cardRect(QStringLiteral("read")).isEmpty() &&
              board->familyAt(board->cardRect(QStringLiteral("read")).center()) ==
                  QStringLiteral("read") &&
              board->cardRect(QStringLiteral("read")).top() <
                  board->cardRect(QStringLiteral("write")).top(),
          QStringLiteral("the board promotes the observed family with its live saving"));

    // Clicking a card's toggle switches the family off: the setting, the
    // launch options, the ledger, and the board all agree, and a Bash call
    // that still arrives is counted as made while off.
    window.testSetAgentToolFamilyEnabled(QStringLiteral("bash"), true);
    const QRect bashToggle = board->toggleRect(QStringLiteral("bash"));
    check(!bashToggle.isEmpty() && board->familyEnabled(QStringLiteral("bash")) &&
              board->cardRect(QStringLiteral("bash")).contains(bashToggle),
          QStringLiteral("every card carries an on/off toggle inside its rect"));
    {
        QMouseEvent press(QEvent::MouseButtonPress, QPointF(bashToggle.center()),
                          board->mapToGlobal(bashToggle.center()), Qt::LeftButton,
                          Qt::LeftButton, Qt::NoModifier);
        QApplication::sendEvent(board, &press);
        QApplication::processEvents();
    }
    check(!board->familyEnabled(QStringLiteral("bash")) &&
              window.testDisabledAgentToolFamilies() == QStringList{QStringLiteral("bash")} &&
              QSettings().value(AgentToolPolicy::DisabledFamiliesSetting).toStringList() ==
                  QStringList{QStringLiteral("bash")} &&
              ledger->disabledFamilies().contains(QStringLiteral("bash")) &&
              window.testAgentRuntimeLaunchOptions()
                      .value(AgentToolPolicy::LaunchOption)
                      .toArray()
                      .contains(QJsonValue(QStringLiteral("bash"))) &&
              board->tileValue(QStringLiteral("Coverage")).startsWith(QStringLiteral("1 /")),
          QStringLiteral("clicking the toggle switches the Shell family off everywhere"));

    // Ending the turn abandons anything still in flight.
    window.testApplyTranscriptEvent(
        session.id,
        block(QJsonObject{{QStringLiteral("type"), QStringLiteral("tool_use")},
                          {QStringLiteral("id"), QStringLiteral("toolu_eff_2")},
                          {QStringLiteral("name"), QStringLiteral("Bash")},
                          {QStringLiteral("input"),
                           QJsonObject{{QStringLiteral("command"), QStringLiteral("ls")}}}},
              QStringLiteral("assistant")));
    window.testApplyTranscriptEvent(
        session.id, QJsonObject{{QStringLiteral("type"), QStringLiteral("result")},
                                {QStringLiteral("subtype"), QStringLiteral("success")},
                                {QStringLiteral("num_turns"), 1}});
    check(ledger->stats(QStringLiteral("bash")).calls == 1 &&
              ledger->stats(QStringLiteral("bash")).inFlight == 0 &&
              ledger->totals().inFlight == 0,
          QStringLiteral("a turn result abandons in-flight calls"));
    window.testRefreshAgentEfficiencyBoard();
    QApplication::processEvents();
    check(ledger->stats(QStringLiteral("bash")).callsWhileOff == 1,
          QStringLiteral("a Bash call that still arrives is counted as made while off"));

    // The same unanswered, switched-off Bash call lands in the realtime
    // improvement log, its JSONL file, the board's feed, and the digest.
    const auto improvementKinds = [improvements] {
        QStringList kinds;
        for (const AgentToolImprovement &signal : improvements->improvements())
            kinds << signal.kind + QLatin1Char('/') + signal.family;
        kinds.sort();
        return kinds;
    };
    check(improvementKinds() ==
                  QStringList{QStringLiteral("abandoned-call/bash"),
                              QStringLiteral("called-while-off/bash")} &&
              QFile::exists(improvements->logPath()) &&
              improvements->logPath().endsWith(QStringLiteral("/tool-improvements.jsonl")) &&
              board->improvementRowCount() == 2 &&
              board->improvementRowTitle(0).contains(QStringLiteral("Shell")) &&
              !board->improvementRowRect(0).isEmpty() &&
              board->improvementRowRect(1).bottom() <
                  board->cardRect(QStringLiteral("read")).top() &&
              improvements->digestMarkdown().contains(
                  QStringLiteral("Used while switched off")),
          QStringLiteral("improvement signals are logged in realtime and fed to "
                         "the board (%1)")
              .arg(improvementKinds().join(QStringLiteral(", "))));

    // Once signals exist, Send to agent hands the same digest Copy improvements
    // copies to an agent, wrapped in the ask to fix each signal at its source.
    const QString fixPrompt = window.testAgentToolImprovementsFixPrompt();
    check(fixPrompt.startsWith(
              QStringLiteral("Please fix the tool efficiency improvements below")) &&
              fixPrompt.contains(QStringLiteral("fix it at the source")) &&
              fixPrompt.contains(QStringLiteral("untrusted evidence")) &&
              fixPrompt.contains(QStringLiteral("improves itself")) &&
              fixPrompt.endsWith(improvements->digestMarkdown(
                  25, improvements->sentLogPath())) &&
              fixPrompt.contains(QStringLiteral("Used while switched off")) &&
              fixPrompt.contains(improvements->sentLogPath()),
          QStringLiteral("Send to agent wraps the improvement digest in fix "
                         "instructions (%1 chars)")
              .arg(fixPrompt.size()));

    // Clicking a card (not its toggle) opens the family details on the right.
    QWidget *detailsPanel = window.testAgentEfficiencyDetailsPanel();
    QTextBrowser *details = window.testAgentEfficiencyDetails();
    check(detailsPanel && details && !detailsPanel->isVisibleTo(&window),
          QStringLiteral("family details stay closed until a card is clicked"));
    const QRect bashCard = board->cardRect(QStringLiteral("bash"));
    QPoint cardPoint(bashCard.left() + 20, bashCard.center().y());
    {
        QMouseEvent press(QEvent::MouseButtonPress, QPointF(cardPoint),
                          board->mapToGlobal(cardPoint), Qt::LeftButton,
                          Qt::LeftButton, Qt::NoModifier);
        QApplication::sendEvent(board, &press);
        QApplication::processEvents();
    }
    const QWidget *boardScroll =
        window.findChild<QWidget *>(QStringLiteral("agentEfficiencyScroll"));
    check(detailsPanel && details && detailsPanel->isVisibleTo(&window) &&
              board->selectedFamily() == QStringLiteral("bash") &&
              board->familyEnabled(QStringLiteral("bash")) == false &&
              details->toPlainText().contains(QStringLiteral("Unanswered call")) &&
              details->toPlainText().contains(QStringLiteral("Calls: 1")) &&
              boardScroll &&
              boardScroll->mapTo(&window, QPoint(boardScroll->width(), 0)).x() <=
                  detailsPanel->mapTo(&window, QPoint(0, 0)).x(),
          QStringLiteral("clicking a card opens its details to the right of the "
                         "board without flipping its switch"));
    if (auto *close = window.findChild<QPushButton *>(
            QStringLiteral("agentEfficiencyDetailsClose"))) {
        close->click();
        QApplication::processEvents();
    }
    check(detailsPanel && !detailsPanel->isVisibleTo(&window) &&
              board->selectedFamily().isEmpty(),
          QStringLiteral("closing the details clears the selected card"));
    window.testSetAgentToolFamilyEnabled(QStringLiteral("bash"), true);
    check(board->familyEnabled(QStringLiteral("bash")) &&
              window.testDisabledAgentToolFamilies().isEmpty() &&
              !QSettings().contains(AgentToolPolicy::DisabledFamiliesSetting) &&
              !window.testAgentRuntimeLaunchOptions().contains(AgentToolPolicy::LaunchOption),
          QStringLiteral("switching the family back on clears the policy"));

    AgentRunEfficiencyLog *runLog = window.testAgentRunLog();
    AgentRunTable *runTable = window.testAgentRunTable();
    auto *runsView = window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyRunsView"));
    if (runLog) {
        AgentRunEfficiencyLog::RunContext run{77, QStringLiteral("Runs view"),
                                              QStringLiteral("claude-code"),
                                              QStringLiteral("claude-sonnet-5"),
                                              {QStringLiteral("read")}};
        runLog->ingest(run, QJsonObject{{QStringLiteral("type"), QStringLiteral("result")},
                                        {QStringLiteral("subtype"), QStringLiteral("success")},
                                        {QStringLiteral("duration_ms"), 1200}});
    }
    if (runsView)
        runsView->click();
    QApplication::processEvents();
    check(runLog && runTable && runsView && runTable->isVisibleTo(&window) &&
              runLog->logPath().endsWith(QStringLiteral("/agent-runs.jsonl")) &&
              runTable->comparisonTable()->rowCount() >= 1 &&
              runTable->runTable()->rowCount() >= 1 &&
              runTable->runTable()->findItems(QStringLiteral("Off: read"), Qt::MatchExactly)
                      .size() >= 1,
          QStringLiteral("Runs lists each run and compares tool configurations"));
    AgentPerformanceHistory *performance = window.testAgentPerformanceHistory();
    AgentPerformanceCharts *charts = window.testAgentPerformanceCharts();
    window.testSampleAgentPerformance();
    auto *trendsView =
        window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyTrendsView"));
    if (trendsView)
        trendsView->click();
    QApplication::processEvents();
    check(performance && charts && trendsView && charts->isVisibleTo(&window) &&
              trendsView->isChecked() && charts->chartCount() == 12 &&
              performance->persistPath().endsWith(QStringLiteral("/performance-history.json")) &&
              charts->chartValue(QStringLiteral("runs")) != QStringLiteral("–") &&
              charts->chartValue(QStringLiteral("agents")) != QStringLiteral("–"),
          QStringLiteral("Trends charts a finished run and the agent sample (runs=%1 agents=%2)")
              .arg(charts ? charts->chartValue(QStringLiteral("runs")) : QString(),
                   charts ? charts->chartValue(QStringLiteral("agents")) : QString()));
    if (auto *hour = window.findChild<QPushButton *>(QStringLiteral("agentPerformancePeriod0")))
        hour->click();
    QApplication::processEvents();
    const QRect runsPlot = charts ? charts->plotRect(QStringLiteral("runs")) : QRect();
    check(charts && charts->period() == AgentPerformanceHistory::Hour &&
              charts->columns() >= 1 && runsPlot.isValid() &&
              charts->tooltipAt(QPoint(runsPlot.right(), runsPlot.center().y()))
                  .contains(QStringLiteral("Runs finished")),
          QStringLiteral("the 1 h period switches every chart and the plot answers hover"));
    if (auto *copySummary =
            window.findChild<QPushButton *>(QStringLiteral("agentPerformanceCopySummary")))
        copySummary->click();
    check(QGuiApplication::clipboard()->text().contains(QStringLiteral("| Runs finished |")),
          QStringLiteral("Copy summary puts the period table on the clipboard"));
    if (auto *familiesView =
            window.findChild<QPushButton *>(QStringLiteral("agentEfficiencyFamiliesView")))
        familiesView->click();

    QString error;
    check(ledger->save(&error) && QFile::exists(ledger->persistPath()) &&
              ledger->persistPath().endsWith(QStringLiteral("/tool-efficiency.json")),
          QStringLiteral("the ledger persists beside the agent store: %1").arg(error));

    // Guardrails sits beside Tool efficiency in the list's action bar.
    backButton->click();
    QApplication::processEvents();
    auto *guardrailsButton =
        window.findChild<QPushButton *>(QStringLiteral("agentGuardrailsButton"));
    auto *guardrailsBack =
        window.findChild<QPushButton *>(QStringLiteral("agentGuardrailsBack"));
    const int guardrailsIndex =
        guardrailsButton ? int(barOrder.indexOf(guardrailsButton)) : -3;
    check(guardrailsButton && guardrailsButton->isVisibleTo(&window) &&
              guardrailsButton->text() == QStringLiteral("Guardrails") &&
              guardrailsIndex == efficiencyIndex + 1 && guardrailsBack,
          QStringLiteral("Guardrails is a button beside Tool efficiency "
                         "(efficiency=%1 guardrails=%2)")
              .arg(efficiencyIndex)
              .arg(guardrailsIndex));
    if (guardrailsButton)
        guardrailsButton->click();
    QApplication::processEvents();
    AgentGuardrailBoard *guardrailBoard = window.testAgentGuardrailBoard();
    AgentGuardrailLedger *guardrailLedger = window.testAgentGuardrailLedger();
    check(stack->currentIndex() == 2 && guardrailBoard && guardrailLedger &&
              guardrailBoard->isVisibleTo(&window) && !board->isVisibleTo(&window) &&
              listPane && !listPane->isVisibleTo(&window),
          QStringLiteral("the Guardrails button opens the guardrail board "
                         "(page=%1)")
              .arg(stack->currentIndex()));
    if (guardrailBoard && guardrailLedger) {
        guardrailLedger->clear();
        const QString guardedRepository =
            QStringLiteral("forkmesh/efficiency-probe");
        window.testSetRepoAgentGuardrails(repositoryIndex, true,
                                          {QStringLiteral("no-such-dir")});
        guardrailLedger->recordBlocked(guardedRepository, QStringLiteral("Read"),
                                       QStringLiteral("secrets/key.pem"), false);
        guardrailLedger->recordBlocked(guardedRepository, QStringLiteral("Bash"),
                                       QStringLiteral("/etc/passwd"), true);
        guardrailLedger->recordDecision(guardedRepository, true);
        guardrailLedger->recordDecision(guardedRepository, false);
        guardrailLedger->recordAgentsStopped(guardedRepository, 2);
        window.testRefreshAgentGuardrailBoard();
        QApplication::processEvents();
        check(guardrailBoard->tileValue(QStringLiteral("Blocked tool calls")) ==
                      QStringLiteral("2") &&
                  guardrailBoard->tileNote(QStringLiteral("Blocked tool calls"))
                      .contains(QStringLiteral("1 outside")) &&
                  guardrailBoard->tileValue(QStringLiteral("Approved")) ==
                      QStringLiteral("1") &&
                  guardrailBoard->tileNote(QStringLiteral("Approved")) ==
                      QStringLiteral("1 denied") &&
                  guardrailBoard->tileValue(QStringLiteral("Agents stopped")) ==
                      QStringLiteral("2"),
              QStringLiteral("the Guardrails tiles count blocked calls, answers, "
                             "and stopped agents (blocked %1, approved %2, "
                             "stopped %3)")
                  .arg(guardrailBoard->tileValue(QStringLiteral("Blocked tool calls")),
                       guardrailBoard->tileValue(QStringLiteral("Approved")),
                       guardrailBoard->tileValue(QStringLiteral("Agents stopped"))));
        check(guardrailBoard->cardHeadline(guardedRepository) ==
                      QStringLiteral("2 blocked calls") &&
                  guardrailBoard->cardNote(guardedRepository)
                      .contains(QStringLiteral("no-such-dir")) &&
                  guardrailBoard->tileNote(QStringLiteral("Guarded repositories"))
                      .contains(QStringLiteral("attention")),
              QStringLiteral("a guarded repository card shows its blocked calls "
                             "and flags a missing allowed directory (%1 / %2)")
                  .arg(guardrailBoard->cardHeadline(guardedRepository),
                       guardrailBoard->cardNote(guardedRepository)));
        const QRect guardedCard = guardrailBoard->cardRect(guardedRepository);
        check(guardedCard.isValid() &&
                  guardrailBoard->repositoryAt(guardedCard.center()) ==
                      guardedRepository &&
                  static_cast<bool>(guardrailBoard->repositoryActivated),
              QStringLiteral("a guardrail card is clickable and routes to its "
                             "repository settings"));
        QString guardrailError;
        check(guardrailLedger->save(&guardrailError) &&
                  guardrailLedger->persistPath().endsWith(
                      QStringLiteral("/guardrails.json")),
              QStringLiteral("the guardrail ledger persists beside the agent "
                             "store: %1")
                  .arg(guardrailError));
        guardrailLedger->clear();
        window.testSetRepoAgentGuardrails(repositoryIndex, false, {});
    }

    if (guardrailsBack)
        guardrailsBack->click();
    QApplication::processEvents();
    check(stack->currentIndex() == 0 && listPane && listPane->isVisibleTo(&window) &&
              (!guardrailBoard || !guardrailBoard->isVisibleTo(&window)),
          QStringLiteral("the guardrail board's back button restores the session "
                         "list"));

    auto *modelsButton =
        window.findChild<QPushButton *>(QStringLiteral("agentModelsButton"));
    const int modelsIndex =
        modelsButton ? int(barOrder.indexOf(modelsButton)) : -4;
    check(modelsButton && modelsButton->isVisibleTo(&window) &&
              modelsButton->text() == QStringLiteral("Models") &&
              modelsIndex == guardrailsIndex + 1,
          QStringLiteral("Models is a button beside Guardrails (guardrails=%1 models=%2)")
              .arg(guardrailsIndex)
              .arg(modelsIndex));
    window.testApplyTranscriptEvent(
        session.id, QJsonObject{{QStringLiteral("type"), QStringLiteral("system")},
                                {QStringLiteral("subtype"), QStringLiteral("init")}});
    if (modelsButton)
        modelsButton->click();
    QApplication::processEvents();
    AgentModelTable *modelTable = window.testAgentModelTable();
    check(stack->currentIndex() == 3 && modelTable && modelTable->isVisibleTo(&window) &&
              modelTable->columnCount() >= 20 && modelTable->rowCount() >= 5 &&
              modelTable->isSortingEnabled(),
          QStringLiteral("the Models button opens a sortable table of every model "
                         "(page=%1 rows=%2)")
              .arg(stack->currentIndex())
              .arg(modelTable ? modelTable->rowCount() : -1));
    if (modelTable) {
        const QString sonnet = QStringLiteral("Sonnet 5");
        check(modelTable->cellText(sonnet, AgentModelTable::RunsColumn) ==
                      QStringLiteral("1") &&
                  modelTable->cellText(sonnet, AgentModelTable::LiveColumn) ==
                      QStringLiteral("1") &&
                  modelTable->cellText(sonnet, AgentModelTable::ToolCallsColumn) !=
                      QStringLiteral("—"),
              QStringLiteral("the running Sonnet 5 probe counts as a live run with "
                             "tool calls (runs=%1 live=%2 tools=%3)")
                  .arg(modelTable->cellText(sonnet, AgentModelTable::RunsColumn),
                       modelTable->cellText(sonnet, AgentModelTable::LiveColumn),
                       modelTable->cellText(sonnet, AgentModelTable::ToolCallsColumn)));
        modelTable->sortItems(AgentModelTable::RunsColumn, Qt::DescendingOrder);
        const QTableWidgetItem *top = modelTable->item(0, AgentModelTable::ModelColumn);
        check(top && top->text() == sonnet && !top->icon().isNull(),
              QStringLiteral("sorting by runs puts the used model first, with its "
                             "agent icon (%1)")
                  .arg(top ? top->text() : QString()));
        QTableWidgetItem *show = modelTable->item(0, AgentModelTable::ShowColumn);
        const QString showKey =
            show ? show->data(Qt::UserRole + 1).toString() : QString();
        const bool startedShown = show && show->checkState() == Qt::Checked;
        if (show && !showKey.isEmpty())
            show->setCheckState(Qt::Unchecked);
        const bool hiddenSaved = forkmesh::ui::hiddenComposerModels().contains(showKey);
        if (show && !showKey.isEmpty())
            show->setCheckState(Qt::Checked);
        check(!showKey.isEmpty() && startedShown && hiddenSaved &&
                  !forkmesh::ui::hiddenComposerModels().contains(showKey),
              QStringLiteral("the Show checkbox hides and restores a model in the "
                             "composer dropdown (key=%1)")
                  .arg(showKey));
    }
    if (auto *modelsBack =
            window.findChild<QPushButton *>(QStringLiteral("agentModelsBack")))
        modelsBack->click();
    QApplication::processEvents();
    check(stack->currentIndex() == 0,
          QStringLiteral("the model board's back button restores the session list"));
    efficiencyButton->click();
    QApplication::processEvents();
    backButton->click();
    QApplication::processEvents();
    check(stack->currentIndex() == 0 && listPane && listPane->isVisibleTo(&window) &&
              !board->isVisibleTo(&window),
          QStringLiteral("the board's back button restores the session list"));
    ledger->clear();
    improvements->clear();
    window.testRemoveAgentSession(session.id);
}

void checkAgentFireball(MainWindow &window)
{
    const auto purplePixelCount = [](const QImage &source) {
        const QImage image = source.convertToFormat(QImage::Format_RGBA8888);
        int count = 0;
        for (int y = 0; y < image.height(); ++y) {
            for (int x = 0; x < image.width(); ++x) {
                const QColor pixel = image.pixelColor(x, y);
                if (pixel.alpha() > 24 && pixel.blue() > pixel.green() + 12 &&
                    pixel.red() > pixel.green() + 8)
                    ++count;
            }
        }
        return count;
    };
    const auto hotCenter = [](const QImage &source) {
        const QImage image = source.convertToFormat(QImage::Format_RGBA8888);
        QPointF sum;
        int count = 0;
        for (int y = 0; y < image.height(); ++y) {
            for (int x = 0; x < image.width(); ++x) {
                const QColor pixel = image.pixelColor(x, y);
                if (pixel.alpha() > 96 && pixel.red() > 220 &&
                    pixel.green() > 185 && pixel.blue() > 235) {
                    sum += QPointF(x, y);
                    ++count;
                }
            }
        }
        return count > 0 ? sum / count : QPointF(-1, -1);
    };

    const QImage fireballTop =
        forkmesh::ui::agentRunningFireballPixmap(20, 0).toImage();
    const QImage fireballRight =
        forkmesh::ui::agentRunningFireballPixmap(20, 90).toImage();
    const QPointF topHead = hotCenter(fireballTop);
    const QPointF rightHead = hotCenter(fireballRight);
    check(purplePixelCount(fireballTop) > 0 &&
              topHead.y() < fireballTop.height() * 0.38 &&
              rightHead.x() > fireballRight.width() * 0.62,
          QStringLiteral("the purple fireball head moves clockwise from "
                         "twelve to three o'clock as its angle increases"));

    forkmesh::ui::AgentDotMatrix matrix;
    forkmesh::ui::AgentDotMatrix::Dot dot;
    dot.sessionId = 181801;
    dot.color = QColor("#3fb950"); // running paint must override this green
    dot.running = true;
    matrix.setDots({dot});
    matrix.show();
    QApplication::processEvents();
    check(purplePixelCount(matrix.grab().toImage()) > 0,
          QStringLiteral("a running agent's chrome-grid dot is purple"));
    {
        struct PaintCounter : QObject {
            int paints = 0;
            bool eventFilter(QObject *, QEvent *event) override
            {
                if (event->type() == QEvent::Paint)
                    ++paints;
                return false;
            }
        } counter;
        QApplication::processEvents();
        matrix.installEventFilter(&counter);
        constexpr int kWindowMs = 900;
        QElapsedTimer clock;
        clock.start();
        int beats = 0;
        while (clock.elapsed() < kWindowMs) {
            dot.intensity = 0.05 + (beats % 10) / 10.0;
            matrix.setDots({dot});
            ++beats;
            QElapsedTimer beat;
            beat.start();
            while (beat.elapsed() < 45)
                QApplication::processEvents(QEventLoop::AllEvents, 5);
        }
        matrix.removeEventFilter(&counter);
        check(matrix.sweeping() && beats > 5 &&
                  counter.paints <= kWindowMs / 60 + 3,
              QStringLiteral("a running dot's meter changes ride the sweep's "
                             "frames instead of adding their own (%1 paints "
                             "for %2 meter beats)")
                  .arg(counter.paints)
                  .arg(beats));
    }
    matrix.hide();

    // The focused mode starts without a repository, so lazily construct the
    // Agents detail page before asking it to render the selected status pill.
    QTemporaryDir focusedRepo;
    if (!window.findChild<QToolButton *>(QStringLiteral("agentStatusPill"))) {
        const bool repoReady = initGitRepo(focusedRepo);
        const int repoIndex =
            repoReady
                ? window.testAddLocalRepository(QStringLiteral("me"),
                                                QStringLiteral("r"),
                                                focusedRepo.path())
                : -1;
        check(repoIndex >= 0 && window.testOpenRepository(repoIndex),
              QStringLiteral("the focused fireball fixture opens an Agents repo"));
        window.testClickRepoDetailTab(3);
    }
    QApplication::processEvents();
    AgentSession spinningPill;
    spinningPill.id = 181802;
    spinningPill.owner = QStringLiteral("me");
    spinningPill.name = QStringLiteral("r");
    spinningPill.provider = QStringLiteral("claude-code");
    spinningPill.model = QStringLiteral("claude-opus-4-1");
    spinningPill.prompt = QStringLiteral("Animated pill fixture");
    spinningPill.status = AgentStatus::Running;
    window.testAddAgentSession(spinningPill);
    window.testAgentMetaHtml(spinningPill.id);
    QToolButton *pill = window.findChild<QToolButton *>(
        QStringLiteral("agentStatusPill"));
    const QImage firstFrame =
        pill ? pill->icon().pixmap(QSize(44, 44)).toImage() : QImage();
    for (int frame = 0; frame < 3; ++frame)
        window.testAnimateRunningAgentIcons();
    const QImage laterFrame =
        pill ? pill->icon().pixmap(QSize(44, 44)).toImage() : QImage();
    check(pill && pill->text().contains(QStringLiteral("Opus")) &&
              pill->text().contains(QStringLiteral("running")) &&
              !firstFrame.isNull() && firstFrame != laterFrame &&
              purplePixelCount(laterFrame) > 0,
          QStringLiteral("the Opus-is-running detail pill advances its purple "
                         "fireball on agent animation ticks"));

    // A change of speed has to bend the orbit, not teleport the head: the angle
    // is carried forward frame by frame, so even when the activity meter slams
    // from idle to full every step stays inside one frame's worth of travel -
    // while the steps do grow, so the fireball still visibly speeds up.
    const auto spinSteps = [&window](int sessionId, int frames) {
        QList<qreal> steps;
        qreal previous = window.testAgentSpinAngle(sessionId);
        for (int frame = 0; frame < frames; ++frame) {
            window.testAnimateRunningAgentIcons();
            const qreal now = window.testAgentSpinAngle(sessionId);
            steps.append(std::fmod(now - previous + 360.0, 360.0));
            previous = now;
        }
        return steps;
    };
    const auto everyStepForward = [](const QList<qreal> &steps, qreal limit) {
        if (steps.isEmpty())
            return false;
        for (const qreal step : steps)
            if (step <= 0.0 || step > limit)
                return false;
        return true;
    };
    const auto meanStep = [](const QList<qreal> &steps) {
        qreal sum = 0.0;
        for (const qreal step : steps)
            sum += step;
        return steps.isEmpty() ? 0.0 : sum / steps.size();
    };
    const QList<qreal> idleSteps = spinSteps(spinningPill.id, 6);
    window.testNoteAgentActivity(spinningPill.id, 4096); // a full-tilt output burst
    const QList<qreal> busySteps = spinSteps(spinningPill.id, 6);
    constexpr qreal kMaxFrameStep = 48.0; // 24 deg/frame x the two-frame clamp
    check(everyStepForward(idleSteps, kMaxFrameStep) &&
              everyStepForward(busySteps, kMaxFrameStep) &&
              meanStep(busySteps) > meanStep(idleSteps),
          QStringLiteral("the fireball keeps orbiting forward and eases into a "
                         "faster spin instead of jumping when output picks up"));
    window.testRemoveAgentSession(spinningPill.id);
}

// Deleting a node forces an immediate catalog sweep, in the middle of the burst
// the deletion itself just sent at the relay. One Cloudflare 429 puts the whole
// host in cooldown and every request in that round is suppressed — and the
// sweep's result used to be assigned wholesale, so the empty round blanked the
// owner / version / platform / mirrors / CPU / RAM / disk columns for the whole
// fleet. A round proves a node gone only for repositories it actually re-read.
void checkNodesCatalogSweepMerge()
{
    const auto record = [](const QString &version, const QStringList &sources) {
        QJsonArray mirrorSources;
        for (const QString &source : sources)
            mirrorSources.append(source);
        return QJsonObject{
            {QStringLiteral("version"), version},
            {QStringLiteral("mirrorSources"), mirrorSources},
        };
    };
    const QHash<QString, QJsonObject> known{
        {QStringLiteral("mirror9"),
         record(QStringLiteral("0.7.1"), {QStringLiteral("jett/forkmesh")})},
        {QStringLiteral("mirror14"),
         record(QStringLiteral("0.7.0"), {QStringLiteral("jett/notes")})},
    };

    const QHash<QString, QJsonObject> afterFailedRound =
        forkmesh::ui::mergeNodesCatalogSweep(known, {}, {});
    check(afterFailedRound.value(QStringLiteral("mirror9"))
                  .value(QStringLiteral("version"))
                  .toString() == QStringLiteral("0.7.1") &&
              afterFailedRound.size() == known.size(),
          QStringLiteral("a catalog round that reached nothing keeps every "
                         "node's last-known stats"));

    // One repository answered; the other was suppressed. Only the answered
    // one's absences are real.
    QHash<QString, QJsonObject> partial;
    partial.insert(QStringLiteral("mirror9"),
                   record(QStringLiteral("0.7.2"),
                          {QStringLiteral("jett/forkmesh")}));
    const QHash<QString, QJsonObject> afterPartialRound =
        forkmesh::ui::mergeNodesCatalogSweep(
            known, partial, {QStringLiteral("jett/forkmesh")});
    check(afterPartialRound.value(QStringLiteral("mirror9"))
                  .value(QStringLiteral("version"))
                  .toString() == QStringLiteral("0.7.2"),
          QStringLiteral("a catalog round refreshes the nodes it did read"));
    check(afterPartialRound.value(QStringLiteral("mirror14"))
                  .value(QStringLiteral("version"))
                  .toString() == QStringLiteral("0.7.0"),
          QStringLiteral("a node whose repositories went unread keeps its stats"));

    // Re-reading every repository a node mirrored, and not finding it, is the
    // one thing that does retire it.
    const QHash<QString, QJsonObject> afterFullRound =
        forkmesh::ui::mergeNodesCatalogSweep(
            known, partial,
            {QStringLiteral("jett/forkmesh"), QStringLiteral("jett/notes")});
    check(!afterFullRound.contains(QStringLiteral("mirror14")),
          QStringLiteral("a node missing from a fully re-read repository is dropped"));

    // A node seen again by one repository must not lose the mirrors it holds
    // for a repository this round never reached.
    QHash<QString, QJsonObject> twoRepoKnown;
    twoRepoKnown.insert(QStringLiteral("mirror9"),
                        record(QStringLiteral("0.7.1"),
                               {QStringLiteral("jett/forkmesh"),
                                QStringLiteral("jett/notes")}));
    const QJsonArray mergedSources =
        forkmesh::ui::mergeNodesCatalogSweep(twoRepoKnown, partial,
                                             {QStringLiteral("jett/forkmesh")})
            .value(QStringLiteral("mirror9"))
            .value(QStringLiteral("mirrorSources"))
            .toArray();
    check(mergedSources.contains(QJsonValue(QStringLiteral("jett/forkmesh"))) &&
              mergedSources.contains(QJsonValue(QStringLiteral("jett/notes"))),
          QStringLiteral("an unread repository stays on a refreshed node's "
                         "mirror list"));
}

int runMirrorFleetOnly(MainWindow &window)
{
    window.testShowHostsSection();
    QApplication::processEvents();
    check(!window.findChild<QCheckBox *>(QStringLiteral("healthyMirrorFleetEnabled")) &&
              !window.findChild<QSpinBox *>(QStringLiteral("desiredHealthyMirrorCount")) &&
              !window.findChild<QLabel *>(QStringLiteral("healthyMirrorFleetStatus")) &&
              !window.findChild<QTimer *>(QStringLiteral("healthyMirrorFleetTimer")),
          QStringLiteral("the old mirror fleet sizing is gone from Hosts"));
    auto *panel = dynamic_cast<FleetAutoscalePanel *>(
        window.findChild<QFrame *>(QStringLiteral("fleetAutoscalePanel")));
    check(panel != nullptr,
          QStringLiteral("Network > Hosts carries the fleet autoscaling panel"));
    if (!panel) {
        stopChildProcesses(window);
        return 1;
    }
    check(panel->scriptPath().endsWith(QStringLiteral("fake_next_autoscale.py")),
          QStringLiteral("the panel runs the scaler found through the tool lookup"));
    for (const char *name :
         {"fleetAutoscaleAppEnabled", "fleetAutoscaleRunnerEnabled",
          "fleetAutoscaleAppDryRun", "fleetAutoscaleRunnerDryRun"}) {
        check(panel->findChild<QCheckBox *>(QLatin1String(name)) != nullptr,
              QStringLiteral("the panel has %1").arg(QLatin1String(name)));
    }
    for (const char *name :
         {"fleetAutoscaleSave", "fleetAutoscaleRefresh", "fleetAutoscaleAppScaleUp",
          "fleetAutoscaleAppScaleDown", "fleetAutoscaleRunnerScaleUp",
          "fleetAutoscaleRunnerScaleDown"}) {
        check(panel->findChild<QPushButton *>(QLatin1String(name)) != nullptr,
              QStringLiteral("the panel has %1").arg(QLatin1String(name)));
    }
    panel->refresh();
    QElapsedTimer waited;
    waited.start();
    while (panel->nodeRowCount(false) != 1 && waited.elapsed() < 15000) {
        QApplication::processEvents(QEventLoop::AllEvents, 50);
        QThread::msleep(20);
    }
    check(panel->nodeRowCount(false) == 1 && panel->nodeRowCount(true) == 0,
          QStringLiteral("a refresh loads the scaler status into the node tables"));
    const QString text = panel->statusText();
    check(text.contains(QStringLiteral("running on the cores (owner n2")) &&
              text.contains(QStringLiteral("verified")) &&
              text.contains(QStringLiteral("$0.42 of $15.00")) &&
              text.contains(QStringLiteral("p95 812 ms")),
          QStringLiteral("the panel shows the service, signed settings, spend and signals: ") +
              text);
    {
        QFile written(qEnvironmentVariable("FMNEXT_CONFIG_DIR") +
                      QStringLiteral("/autoscaled-instances.json"));
        const bool opened = written.open(QIODevice::ReadOnly);
        const QJsonObject nodes = QJsonDocument::fromJson(written.readAll()).object();
        check(opened && nodes.value(QStringLiteral("fmnext-auto-1")).toObject()
                                .value(QStringLiteral("ip"))
                                .toString() == QStringLiteral("192.0.2.21") &&
                  (written.permissions() & (QFileDevice::ReadGroup | QFileDevice::ReadOther)) == 0,
              QStringLiteral("a status refresh writes the autoscaled nodes, owner-only, "
                             "for node-log discovery"));
    }
    check(panel->findChild<QCheckBox *>(QStringLiteral("fleetAutoscaleKillSwitch")) &&
              panel->findChild<QLineEdit *>(QStringLiteral("fleetAutoscaleAppSnapshot")),
          QStringLiteral("the panel has the kill switch and the app pool's snapshot"));
    const forkmesh::autoscale::Settings loaded = panel->settingsFromForm();
    check(loaded.app.enabled && loaded.app.dryRun && loaded.app.max == 2 &&
              !loaded.runner.enabled,
          QStringLiteral("the form shows the signed settings the scaler reported"));
    forkmesh::autoscale::Status unsigned_;
    unsigned_.parsed = true;
    unsigned_.settings = forkmesh::autoscale::defaultSettings();
    unsigned_.settingsError = QStringLiteral("bad signature");
    panel->applyStatus(unsigned_);
    check(panel->statusText().contains(QStringLiteral("NOT verified (bad signature)")) &&
              panel->statusText().contains(QStringLiteral("No core has run")),
          QStringLiteral("unsigned settings and a stopped service are called out"));
    stopChildProcesses(window);
    return failures == 0 ? 0 : 1;
}

void checkInlineDiffCommentRenderer()
{
    const QString reviewPatch =
        QStringLiteral("diff --git a/a.txt b/a.txt\n"
                       "--- a/a.txt\n+++ b/a.txt\n@@ -1 +1 @@\n-old\n+new\n");
    const QString noteKey = QStringLiteral("a.txt") + QLatin1Char('\x1f') +
                            QStringLiteral("new:1");
    QHash<QString, QString> openNotes;
    openNotes.insert(
        noteKey,
        QStringLiteral("<div class='reviewthread'>Existing review</div>"));
    for (bool split : {false, true}) {
        QList<forkmesh::ui::DiffFileEntry> reviewFiles;
        const QString reviewHtml = forkmesh::ui::renderDiffHtmlSplit(
            split, reviewPatch, reviewFiles, QString(), QString(), QString(),
            QStringLiteral("*"), openNotes, {}, {});
        check(reviewHtml.contains(QStringLiteral("threadtoggle:a.txt?s=new&l=1")) &&
                  reviewHtml.contains(QStringLiteral("&#128100;")) &&
                  reviewHtml.contains(QStringLiteral("Existing review")),
              QStringLiteral("%1 diff renders the per-line review avatar")
                  .arg(split ? QStringLiteral("split")
                             : QStringLiteral("unified")));
    }
    QHash<QString, QString> collapsedNotes;
    collapsedNotes.insert(
        noteKey,
        QLatin1Char('\x1c') +
            QStringLiteral("<div class='reviewthread'>Hidden review</div>") +
            QLatin1Char('\x1d') +
            QStringLiteral("<div class='inlinecomposerspace'>Editor row</div>"));
    QList<forkmesh::ui::DiffFileEntry> collapsedFiles;
    const QString collapsedHtml = forkmesh::ui::renderDiffHtmlSplit(
        false, reviewPatch, collapsedFiles, QString(), QString(), QString(),
        QStringLiteral("*"), collapsedNotes, {}, {});
    check(collapsedHtml.contains(QStringLiteral("threadtoggle:")) &&
              !collapsedHtml.contains(QStringLiteral("Hidden review")) &&
              collapsedHtml.contains(QStringLiteral("Editor row")),
          QStringLiteral("a collapsed thread hides only its thread content"));
}

void checkRequestedPullFailureReason(MainWindow &window)
{
    QTemporaryDir pullFailRepo;
    if (initGitRepo(pullFailRepo)) {
        const QString failBranch = QStringLiteral("agent/requested-pr-reason");
        runGitChecked(pullFailRepo.path(), {"checkout", "-q", "-b", failBranch});
        {
            QFile work(pullFailRepo.path() + QStringLiteral("/work.txt"));
            work.open(QIODevice::WriteOnly);
            work.write("agent work\n");
            work.close();
        }
        runGitChecked(pullFailRepo.path(), {"add", "work.txt"});
        runGitChecked(pullFailRepo.path(), {"commit", "-q", "-m", "agent work"});
        runGitChecked(pullFailRepo.path(), {"checkout", "-q", "main"});
        const int failIdx = window.testAddLocalRepository(
            "me", "pullfailrepo", pullFailRepo.path());
        window.testOpenRepository(failIdx);
        QApplication::processEvents();

        AgentSession wantsPr;
        wantsPr.id = 13050;
        wantsPr.owner = QStringLiteral("me");
        wantsPr.name = QStringLiteral("pullfailrepo");
        wantsPr.branchName = failBranch;
        wantsPr.issueTitle = QStringLiteral("requested PR cannot be read");
        wantsPr.baseBranch = QStringLiteral("main");
        wantsPr.baseRef = QStringLiteral("0123456789abcdef0123456789abcdef01234567");
        wantsPr.status = AgentStatus::Success;
        wantsPr.createPr = true;
        window.testAddAgentSession(wantsPr);

        const bool merged = window.testMergeBranchAndCleanUp(failBranch);
        QString notice;
        for (const QString &text : QStringList{window.testLatestNoticeText()} +
                                       window.testNoticeTexts())
            if (text.contains(QStringLiteral("Couldn't create the requested PR")))
                notice = text;
        check(!merged &&
                  notice.contains(QStringLiteral("Agent #13050")) &&
                  notice.contains(
                      QStringLiteral("git could not read the branch's changes")) &&
                  notice.contains(QStringLiteral("0123456789ab")) &&
                  !gitOutput(pullFailRepo.path(), {"branch", "--list", failBranch})
                       .isEmpty(),
              QStringLiteral("a requested PR that git cannot diff keeps the branch "
                             "and the notice names git's reason, not \"No code "
                             "changes\" (%1)")
                  .arg(notice));
        window.testRemoveAgentSession(13050);
    }

    {
        const auto writeRepoFile = [](const QString &path, const QByteArray &text) {
            QFile file(path);
            if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate))
                return false;
            return file.write(text) == text.size();
        };
        const auto settleCleanup = [&window](const QString &branch) {
            QElapsedTimer settle;
            settle.start();
            while (window.testBranchCleanupInProgress(branch) &&
                   settle.elapsed() < 10000)
                QApplication::processEvents(QEventLoop::AllEvents, 20);
        };

        QTemporaryDir landedRepo;
        const QString landed = QStringLiteral("578-already-landed");
        const QString landedPath = landedRepo.path();
        const QString landedWorktree =
            landedPath + QStringLiteral("-wt-") + landed;
        const bool landedReady =
            initGitRepo(landedRepo) &&
            runGitChecked(landedPath, {"checkout", "-b", landed}) &&
            writeRepoFile(landedPath + QStringLiteral("/landed.txt"), "done\n") &&
            runGitChecked(landedPath, {"add", "landed.txt"}) &&
            runGitChecked(landedPath, {"commit", "-m", "landed work"}) &&
            runGitChecked(landedPath, {"checkout", "main"}) &&
            runGitChecked(landedPath,
                          {"merge", "--no-ff", landed, "-m", "land it"}) &&
            runGitChecked(landedPath, {"worktree", "add", landedWorktree, landed});
        const int landedIdx = window.testAddLocalRepository(
            QStringLiteral("me"), QStringLiteral("landedrepo"), landedPath);
        window.testOpenRepository(landedIdx);
        QApplication::processEvents();
        AgentSession landedSession;
        landedSession.id = 15780;
        landedSession.owner = QStringLiteral("me");
        landedSession.name = QStringLiteral("landedrepo");
        landedSession.branchName = landed;
        landedSession.issueTitle = QStringLiteral("work that already landed");
        landedSession.baseBranch = QStringLiteral("main");
        landedSession.baseRef =
            gitOutput(landedPath, {"rev-parse", "main~1"}).trimmed();
        landedSession.status = AgentStatus::Success;
        landedSession.createPr = true;
        landedSession.prNumber = 0;
        window.testAddAgentSession(landedSession);
        const bool landedCleaned = window.testMergeBranchAndCleanUp(landed);
        settleCleanup(landed);
        check(landedReady && landedCleaned &&
                  gitOutput(landedPath, {"branch", "--list", landed})
                      .trimmed()
                      .isEmpty(),
              QStringLiteral("a branch whose work is already in main cleans up "
                             "without insisting on the requested PR"));
        window.testRemoveAgentSession(15780);
        if (QFileInfo::exists(landedWorktree))
            QDir(landedWorktree).removeRecursively();
    }
}

void checkAgentListView(MainWindow &window)
{
    QTemporaryDir viewRepo;
    const int repoIndex =
        initGitRepo(viewRepo)
            ? window.testAddLocalRepository(QStringLiteral("me"),
                                            QStringLiteral("list-view"),
                                            viewRepo.path())
            : -1;
    check(repoIndex >= 0 && window.testOpenRepository(repoIndex),
          QStringLiteral("the list view fixture opens an Agents repo"));
    window.resize(1280, 800);
    window.show();
    window.testClickRepoDetailTab(3);
    QApplication::processEvents();

    AgentSession fixture;
    fixture.id = 181901;
    fixture.owner = QStringLiteral("me");
    fixture.name = QStringLiteral("list-view");
    fixture.issueTitle = QStringLiteral("tidy the release checklist");
    fixture.issueNumber = 42;
    fixture.provider = QStringLiteral("codex");
    fixture.model = QStringLiteral("gpt-5.6-sol");
    fixture.status = AgentStatus::Success;
    fixture.createdAtMs = QDateTime::currentMSecsSinceEpoch() - 5 * 60 * 1000;
    window.testAddAgentSession(fixture);
    AgentSession running = fixture;
    running.id = 181902;
    running.issueNumber = 43;
    running.issueTitle = QStringLiteral("stream the release notes");
    running.provider = QStringLiteral("claude-code");
    running.model = QStringLiteral("claude-opus-5-5");
    running.status = AgentStatus::Running;
    running.createdAtMs = QDateTime::currentMSecsSinceEpoch() - 16 * 60 * 60 * 1000;
    window.testAddAgentSession(running);
    window.testRefreshAgentTable();
    QApplication::processEvents();

    QPushButton *viewButton =
        window.findChild<QPushButton *>(QStringLiteral("agentViewButton"));
    const QImage compactRow = window.testGrabAgentTitleRow(fixture.id);
    QStringList compactTitles = window.testAgentRowTitles();
    compactTitles.removeIf([](const QString &title) {
        return title.contains(QStringLiteral("#43"));
    });
    check(viewButton && viewButton->text() == QStringLiteral("Compact") &&
              !window.testAgentLeadColumnHidden() &&
              window.testAgentRowChipWords(fixture.id).isEmpty() &&
              compactTitles.size() == 1 &&
              compactTitles.first().contains(QStringLiteral("P")) &&
              compactTitles.first().contains(QStringLiteral("#42")),
          QString("the View button over the agent list starts on Compact "
                  "(rows=%1)")
              .arg(compactTitles.join(QStringLiteral(" | "))));

    if (viewButton)
        viewButton->click();
    QApplication::processEvents();
    QStringList zenTitles = window.testAgentRowTitles();
    zenTitles.removeAll(running.issueTitle);
    const QImage zenRow = window.testGrabAgentTitleRow(fixture.id);
    check(viewButton && viewButton->text() == QStringLiteral("Zen") &&
              window.testAgentLeadColumnHidden() &&
              zenTitles == QStringList{fixture.issueTitle} &&
              window.testAgentRowChipWords(fixture.id).isEmpty(),
          QString("a click steps to Zen, which shows nothing but each "
                  "title (rows=%1)")
              .arg(zenTitles.join(QStringLiteral(" | "))));

    if (viewButton)
        viewButton->click();
    QApplication::processEvents();
    const QStringList fullWords = window.testAgentRowChipWords(fixture.id);
    QStringList fullTitles = window.testAgentRowTitles();
    fullTitles.removeAll(QStringLiteral("#43 ") + running.issueTitle);
    const QImage fullRow = window.testGrabAgentTitleRow(fixture.id);
    const QImage runningRow = window.testGrabAgentTitleRow(running.id);
    const auto purplePixels = [](const QImage &source) {
        const QImage image = source.convertToFormat(QImage::Format_RGBA8888);
        int count = 0;
        for (int y = 0; y < image.height(); ++y)
            for (int x = 0; x < image.width(); ++x) {
                const QColor pixel = image.pixelColor(x, y);
                if (pixel.alpha() > 24 && pixel.blue() > pixel.green() + 12 &&
                    pixel.red() > pixel.green() + 8)
                    ++count;
            }
        return count;
    };
    const QStringList runningWords = window.testAgentRowChipWords(running.id);
    check(runningWords.value(0) == QStringLiteral("Running") &&
              runningWords.contains(QStringLiteral("Claude")) &&
              purplePixels(runningRow) > 0 && purplePixels(fullRow) == 0,
          QString("Full marks a running agent with the purple fireball, not "
                  "a blue spinner (words=%1, purple %2 vs %3)")
              .arg(runningWords.join(QStringLiteral(" | ")))
              .arg(purplePixels(runningRow))
              .arg(purplePixels(fullRow)));
    bool oneWordEach = !fullWords.isEmpty();
    for (const QString &word : fullWords)
        oneWordEach = oneWordEach && !word.isEmpty() &&
                      !word.contains(QLatin1Char(' '));
    check(viewButton && viewButton->text() == QStringLiteral("Full") &&
              window.testAgentLeadColumnHidden() && oneWordEach &&
              fullWords.contains(QStringLiteral("Success")) &&
              fullWords.contains(QStringLiteral("Codex")) &&
              fullWords.contains(QStringLiteral("Desktop")) &&
              fullWords.contains(QStringLiteral("5m")) &&
              fullTitles == QStringList{QStringLiteral("#42 ") +
                                        fixture.issueTitle} &&
              !compactRow.isNull() && !fullRow.isNull() &&
              fullRow.height() > compactRow.height(),
          QString("Full puts the title on its own line and one word per "
                  "detail under it (words=%1, rows=%2, heights %3 -> %4)")
              .arg(fullWords.join(QStringLiteral(" | ")),
                   fullTitles.join(QStringLiteral(" | ")))
              .arg(compactRow.height())
              .arg(fullRow.height()));
    const QString shot = qEnvironmentVariable("FORKMESH_AGENT_ROWS_SHOT");
    if (!shot.isEmpty()) {
        compactRow.save(shot + QStringLiteral(".compact.png"));
        zenRow.save(shot + QStringLiteral(".zen.png"));
        fullRow.save(shot + QStringLiteral(".full.png"));
        runningRow.save(shot + QStringLiteral(".running.png"));
    }

    if (viewButton)
        viewButton->click();
    QApplication::processEvents();
    check(viewButton && viewButton->text() == QStringLiteral("Compact") &&
              !window.testAgentLeadColumnHidden() &&
              window.testAgentRowChipWords(fixture.id).isEmpty() &&
              window.testGrabAgentTitleRow(fixture.id).height() ==
                  compactRow.height() &&
              window.testAgentRowTitles().contains(compactTitles.value(0)),
          QStringLiteral("a third click on View returns the agent list to "
                         "Compact"));
    const QImage quietRow = window.testGrabAgentTitleRow(running.id);
    window.testSetTeammateAgentOutput(
        running.id, QStringLiteral("Earlier note.\n\n**Running** the `ticker` "
                                   "tests on the compact row now, then the "
                                   "window suite."));
    window.testAnimateRunningAgentIcons();
    QApplication::processEvents();
    const QImage tickerStart = window.testGrabAgentTitleRow(running.id);
    QElapsedTimer tickerWait;
    tickerWait.start();
    while (tickerWait.elapsed() < 900)
        QApplication::processEvents(QEventLoop::AllEvents, 20);
    const QImage tickerLater = window.testGrabAgentTitleRow(running.id);
    check(!quietRow.isNull() && tickerStart != quietRow &&
              tickerLater != tickerStart,
          QStringLiteral("Compact scrolls a running agent's latest prose after "
                         "its title"));
    if (!shot.isEmpty()) {
        tickerStart.save(shot + QStringLiteral(".ticker-start.png"));
        tickerLater.save(shot + QStringLiteral(".ticker-later.png"));
    }
    window.testSetTeammateAgentOutput(running.id, QString());
    window.testRemoveAgentSession(running.id);
    window.testRemoveAgentSession(fixture.id);
    window.testRefreshAgentTable();
}

void checkAgentFolders(MainWindow &window)
{
    QTemporaryDir folderRepo;
    const int repoIndex =
        initGitRepo(folderRepo)
            ? window.testAddLocalRepository(QStringLiteral("me"),
                                            QStringLiteral("agent-folders"),
                                            folderRepo.path())
            : -1;
    check(repoIndex >= 0 && window.testOpenRepository(repoIndex),
          QStringLiteral("the agent folders fixture opens an Agents repo"));
    window.resize(1280, 800);
    window.show();
    window.testClickRepoDetailTab(3);
    QApplication::processEvents();

    const qint64 now = QDateTime::currentMSecsSinceEpoch();
    QList<int> ids;
    for (int i = 0; i < 3; ++i) {
        AgentSession session;
        session.id = 183101 + i;
        session.owner = QStringLiteral("me");
        session.name = QStringLiteral("agent-folders");
        session.issueTitle = QStringLiteral("folder fixture %1").arg(i + 1);
        session.provider = QStringLiteral("codex");
        session.status = AgentStatus::Success;
        session.priority = i + 1;
        session.createdAtMs = now - (i + 1) * 60 * 1000;
        window.testAddAgentSession(session);
        ids << session.id;
    }
    const QString a = QString::number(ids.at(0));
    const QString b = QString::number(ids.at(1));
    const QString c = QString::number(ids.at(2));
    window.testRefreshAgentTable();
    QApplication::processEvents();
    check(window.testAgentListLayout() == QStringList{a, b, c},
          QStringLiteral("without folders the Agents list is the plain session "
                         "list (rows=%1)")
              .arg(window.testAgentListLayout().join(QStringLiteral(" | "))));

    const QString release =
        window.testCreateAgentFolder(QStringLiteral("  Release   work "),
                                     {ids.at(0), ids.at(2)});
    QApplication::processEvents();
    QStringList rows = window.testAgentListLayout();
    check(!release.isEmpty() &&
              rows == QStringList{QStringLiteral("-[Release work]"), a, c, b},
          QStringLiteral("a new folder heads the list with its agents under it "
                         "(rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));
    check(!window.testAgentRowTitles().contains(QString()),
          QStringLiteral("folder header rows are not reported as agent titles"));

    const auto inkPixels = [](const QImage &source) {
        const QImage image = source.convertToFormat(QImage::Format_RGB32);
        if (image.isNull())
            return 0;
        const QRgb ground = image.pixel(image.width() / 2, 1);
        int count = 0;
        for (int y = 0; y < image.height(); ++y)
            for (int x = 0; x < image.width(); ++x)
                if (qAbs(qGray(image.pixel(x, y)) - qGray(ground)) > 60)
                    ++count;
        return count;
    };
    const QImage compactHeader = window.testGrabAgentFolderRow(release);
    check(inkPixels(compactHeader) > 30,
          QStringLiteral("the folder header paints its name across the row "
                         "(ink %1)")
              .arg(inkPixels(compactHeader)));

    check(window.testClickAgentFolderRow(release),
          QStringLiteral("click the folder header"));
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("+[Release work]"), b},
          QStringLiteral("clicking a folder collapses it (rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));
    check(window.testClickAgentFolderRow(release),
          QStringLiteral("click the folder again"));
    QApplication::processEvents();
    check(window.testAgentListLayout().first() == QStringLiteral("-[Release work]"),
          QStringLiteral("a second click expands it again"));

    const QString later = window.testCreateAgentFolder(QStringLiteral("Later"), {});
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("-[Release work]"), a, c,
                              QStringLiteral("-[Later]"), b},
          QStringLiteral("an empty folder still shows (rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));

    window.testDropAgentFolder(later, release, /*after=*/false);
    QApplication::processEvents();
    check(window.testAgentListLayout().first() == QStringLiteral("-[Later]"),
          QStringLiteral("dropping a folder above another reorders the folders"));

    const QStringList folderMenu = window.testAgentFolderMenuActions(release);
    check(folderMenu.contains(QStringLiteral("agentFolderToggleAction")) &&
              folderMenu.contains(QStringLiteral("agentFolderRenameAction")) &&
              folderMenu.contains(QStringLiteral("agentFolderDeleteAction")) &&
              folderMenu.contains(QStringLiteral("agentFolderSelectAction")) &&
              folderMenu.contains(QStringLiteral("agentFolderMoveUpAction")) &&
              folderMenu.contains(
                  QStringLiteral("agentFolderMoveDownAction(disabled)")) &&
              folderMenu.contains(QStringLiteral("agentFolderCollapseAllAction")),
          QStringLiteral("right-clicking a folder offers its management actions "
                         "(menu=%1)")
              .arg(folderMenu.join(QStringLiteral(" | "))));
    check(folderMenu.contains(
              QStringLiteral("agentFolderStartAllAction(disabled)")) &&
              folderMenu.contains(
                  QStringLiteral("agentFolderStopAllAction(disabled)")),
          QStringLiteral("a folder of finished agents has nothing to start or "
                         "stop (menu=%1)")
              .arg(folderMenu.join(QStringLiteral(" | "))));
    {
        const AgentSession restoreLoose = window.testAgentSession(ids.at(1));
        const AgentSession restoreFiled = window.testAgentSession(ids.at(2));
        AgentSession running = window.testAgentSession(ids.at(2));
        running.status = AgentStatus::Running;
        window.testAddAgentSession(running);
        AgentSession loose = window.testAgentSession(ids.at(1));
        loose.status = AgentStatus::Running;
        window.testAddAgentSession(loose);
        window.testRefreshAgentTable();
        QApplication::processEvents();
        const QStringList runningMenu = window.testAgentFolderMenuActions(release);
        check(runningMenu.contains(QStringLiteral("agentFolderStopAllAction")) &&
                  runningMenu.contains(
                      QStringLiteral("agentFolderStartAllAction(disabled)")),
              QStringLiteral("a folder with a running agent offers Stop all "
                             "(menu=%1)")
                  .arg(runningMenu.join(QStringLiteral(" | "))));
        check(window.testTriggerAgentFolderMenuAction(
                  release, QStringLiteral("agentFolderStopAllAction")),
              QStringLiteral("stop all in the Release folder"));
        QApplication::processEvents();
        check(window.testAgentSession(ids.at(2)).status == AgentStatus::Stopped &&
                  window.testAgentSession(ids.at(1)).status ==
                      AgentStatus::Running,
              QStringLiteral("Stop all in folder stops only that folder's "
                             "agents"));
        const QStringList stoppedMenu = window.testAgentFolderMenuActions(release);
        check(stoppedMenu.contains(QStringLiteral("agentFolderStartAllAction")) &&
                  stoppedMenu.contains(
                      QStringLiteral("agentFolderStopAllAction(disabled)")),
              QStringLiteral("a folder with a stopped agent offers Start all "
                             "(menu=%1)")
                  .arg(stoppedMenu.join(QStringLiteral(" | "))));
        window.testAddAgentSession(restoreLoose);
        window.testAddAgentSession(restoreFiled);
        window.testRefreshAgentTable();
        QApplication::processEvents();
    }
    check(window.testTriggerAgentFolderMenuAction(
              release, QStringLiteral("agentFolderMoveTopAction")) &&
              window.testAgentListLayout().first() ==
                  QStringLiteral("-[Release work]"),
          QStringLiteral("Move to top puts the folder back first"));
    check(window.testTriggerAgentFolderMenuAction(
              release, QStringLiteral("agentFolderCollapseAllAction")),
          QStringLiteral("collapse all folders"));
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("+[Release work]"),
                              QStringLiteral("+[Later]"), b},
          QStringLiteral("Collapse all folders folds every folder (rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));
    window.testTriggerAgentFolderMenuAction(
        release, QStringLiteral("agentFolderExpandAllAction"));
    QApplication::processEvents();

    const QStringList rowMenu = window.testAgentRowFolderMenuActions(ids.at(1));
    check(rowMenu.value(0) == QStringLiteral("Move to folder") &&
              rowMenu.contains(QStringLiteral("agentListFolder:") + release) &&
              rowMenu.contains(QStringLiteral("agentListFolder:") + later) &&
              rowMenu.contains(QStringLiteral("agentListNewFolderAction")) &&
              rowMenu.contains(
                  QStringLiteral("agentListRemoveFromFolderAction(disabled)")),
          QStringLiteral("right-clicking an agent offers Move to folder "
                         "(menu=%1)")
              .arg(rowMenu.join(QStringLiteral(" | "))));
    check(window.testTriggerAgentRowFolderMenuAction(
              ids.at(1), QStringLiteral("agentListFolder:") + later),
          QStringLiteral("move the loose agent into Later"));
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("-[Release work]"), a, c,
                              QStringLiteral("-[Later]"), b},
          QStringLiteral("Move to folder files the agent (rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));

    window.testDropAgentSessions({ids.at(0)}, 0, QString(), true);
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("-[Release work]"), c,
                              QStringLiteral("-[Later]"), b, a},
          QStringLiteral("dropping an agent outside the folders takes it out "
                         "(rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));
    window.testDropAgentSessions({ids.at(0)}, 0, release, false);
    QApplication::processEvents();
    check(window.testAgentListLayout().mid(0, 3) ==
              QStringList({QStringLiteral("-[Release work]"), a, c}),
          QStringLiteral("dropping an agent on a folder header files it there"));

    QPushButton *viewButton =
        window.findChild<QPushButton *>(QStringLiteral("agentViewButton"));
    if (viewButton)
        viewButton->click();
    QApplication::processEvents();
    const QImage zenHeader = window.testGrabAgentFolderRow(release);
    check(viewButton && window.testAgentLeadColumnHidden() &&
              inkPixels(zenHeader) > 30,
          QStringLiteral("the folder header still paints when the lead column "
                         "is hidden (ink %1)")
              .arg(inkPixels(zenHeader)));
    if (viewButton) {
        viewButton->click();
        QApplication::processEvents();
        viewButton->click();
        QApplication::processEvents();
    }
    const QString shot = qEnvironmentVariable("FORKMESH_AGENT_FOLDERS_SHOT");
    if (!shot.isEmpty()) {
        compactHeader.save(shot + QStringLiteral(".compact.png"));
        zenHeader.save(shot + QStringLiteral(".zen.png"));
        if (QWidget *table = window.findChild<QWidget *>(QStringLiteral("issueTable")))
            table->grab().save(shot + QStringLiteral(".list.png"));
    }

    const QString stored =
        QSettings().value(QStringLiteral("agents/folders")).toString();
    check(stored.contains(QStringLiteral("Release work")) &&
              stored.contains(QStringLiteral("me/agent-folders")),
          QStringLiteral("folders are saved per repository"));

    check(window.testTriggerAgentFolderMenuAction(
              release, QStringLiteral("agentFolderDeleteAction")),
          QStringLiteral("delete the Release folder"));
    QApplication::processEvents();
    rows = window.testAgentListLayout();
    check(rows == QStringList{QStringLiteral("-[Later]"), b, a, c} ||
              rows == QStringList{QStringLiteral("-[Later]"), b, c, a},
          QStringLiteral("deleting a folder keeps its agents in the list "
                         "(rows=%1)")
              .arg(rows.join(QStringLiteral(" | "))));
    window.testTriggerAgentFolderMenuAction(
        later, QStringLiteral("agentFolderDeleteAction"));
    for (const int id : ids)
        window.testRemoveAgentSession(id);
    window.testRefreshAgentTable();
}

void checkAgentUnreadDot(MainWindow &window)
{
    const qint64 now = QDateTime::currentMSecsSinceEpoch();
    window.testSetAgentReadBaseline(now - 60 * 1000);
    AgentSession old;
    old.id = 181905;
    old.owner = QStringLiteral("me");
    old.name = QStringLiteral("list-view");
    old.issueTitle = QStringLiteral("an old finished run");
    old.provider = QStringLiteral("codex");
    old.status = AgentStatus::Success;
    old.createdAtMs = now - 10 * 60 * 1000;
    old.finishedAtMs = now - 2 * 60 * 1000;
    window.testAddAgentSession(old);
    AgentSession fresh = old;
    fresh.id = 181906;
    fresh.issueTitle = QStringLiteral("a run that finished just now");
    fresh.finishedAtMs = now - 1000;
    window.testAddAgentSession(fresh);
    AgentSession busy = fresh;
    busy.id = 181907;
    busy.issueTitle = QStringLiteral("a run still going");
    busy.status = AgentStatus::Running;
    window.testAddAgentSession(busy);
    window.testShowAgentSession(old.id);
    window.testRefreshAgentTable();
    QApplication::processEvents();

    const auto payloadUnread = [&window](int id) {
        const QJsonArray rows =
            window.testLocalControlAgentsPayload().value(QStringLiteral("sessions")).toArray();
        for (const QJsonValue &row : rows) {
            const QJsonObject object = row.toObject();
            if (object.value(QStringLiteral("id")).toInt() == id)
                return object.contains(QStringLiteral("unread"))
                           ? (object.value(QStringLiteral("unread")).toBool() ? 1 : 2)
                           : 0;
        }
        return -1;
    };
    const auto dotPixels = [](const QImage &source) {
        const QImage image = source.convertToFormat(QImage::Format_RGBA8888);
        int count = 0;
        for (int y = 0; y < image.height(); ++y)
            for (int x = 0; x < image.width(); ++x) {
                const QColor pixel = image.pixelColor(x, y);
                const bool dark = qAbs(pixel.red() - 0x58) < 30 &&
                                  qAbs(pixel.green() - 0xa6) < 30 &&
                                  qAbs(pixel.blue() - 0xff) < 30;
                const bool light = qAbs(pixel.red() - 0x09) < 30 &&
                                   qAbs(pixel.green() - 0x69) < 30 &&
                                   qAbs(pixel.blue() - 0xda) < 30;
                if (dark || light)
                    ++count;
            }
        return count;
    };
    const int freshDots = dotPixels(window.testGrabAgentTitleRow(fresh.id));
    const int oldDots = dotPixels(window.testGrabAgentTitleRow(old.id));
    const int busyDots = dotPixels(window.testGrabAgentTitleRow(busy.id));
    check(window.testAgentSessionUnread(fresh.id) &&
              window.testAgentRowUnread(fresh.id) &&
              !window.testAgentSessionUnread(old.id) &&
              !window.testAgentRowUnread(old.id) &&
              !window.testAgentSessionUnread(busy.id) &&
              payloadUnread(fresh.id) == 1 && payloadUnread(old.id) == 2 &&
              payloadUnread(busy.id) == 2 && freshDots > oldDots + 10 &&
              freshDots > busyDots + 10,
          QString("an agent that finished since it was last opened shows a "
                  "blue unread dot and agents.list says unread; older and "
                  "running agents do not (payload %1/%2/%3, dots %4/%5/%6)")
              .arg(payloadUnread(fresh.id))
              .arg(payloadUnread(old.id))
              .arg(payloadUnread(busy.id))
              .arg(freshDots)
              .arg(oldDots)
              .arg(busyDots));
    const QString shot = qEnvironmentVariable("FORKMESH_AGENT_ROWS_SHOT");
    if (!shot.isEmpty())
        window.testGrabAgentTitleRow(fresh.id).save(shot + QStringLiteral(".unread.png"));

    window.testMarkAgentSessionRead(fresh.id);
    QApplication::processEvents();
    const bool readCleared = !window.testAgentSessionUnread(fresh.id) &&
                             !window.testAgentRowUnread(fresh.id) &&
                             payloadUnread(fresh.id) == 2;
    const int readDots = dotPixels(window.testGrabAgentTitleRow(fresh.id));
    fresh.finishedAtMs = now + 1000;
    window.testAddAgentSession(fresh);
    window.testRefreshAgentTable();
    QApplication::processEvents();
    const bool unreadAgain = window.testAgentSessionUnread(fresh.id) &&
                             window.testAgentRowUnread(fresh.id);
    window.testShowAgentSession(fresh.id);
    window.testMarkAgentSessionRead(fresh.id);
    window.testRefreshAgentTable();
    QApplication::processEvents();
    check(readCleared && readDots + 10 < freshDots && unreadAgain &&
              !window.testAgentRowUnread(fresh.id),
          QString("opening an agent clears its dot until its next turn "
                  "finishes (cleared=%1 dots=%2 again=%3)")
              .arg(readCleared)
              .arg(readDots)
              .arg(unreadAgain));
    window.testRemoveAgentSession(busy.id);
    window.testRemoveAgentSession(fresh.id);
    window.testRemoveAgentSession(old.id);
    window.testRefreshAgentTable();
}

