        emptyCycleTeammate.id = QStringLiteral("empty-cycle-quality");
        emptyCycleTeammate.name = QStringLiteral("Empty Cycle Quality");
        emptyCycleTeammate.lastSessionId = 943099;
        QString emptyCycleError;
