        const forkmesh::teammates::LoadResult afterEmptyCycle =
            emptyCycleStore.load();
        const forkmesh::teammates::Config beforeEmpty =
            beforeEmptyCycle.teammates.isEmpty()
                ? forkmesh::teammates::Config{}
                : beforeEmptyCycle.teammates.first();
        const forkmesh::teammates::Config afterEmpty =
            afterEmptyCycle.teammates.isEmpty()
                ? forkmesh::teammates::Config{}
                : afterEmptyCycle.teammates.first();
        check(emptyCycleGitReady && emptyCycleSaved &&
                  emptyCycleError.isEmpty() && emptyCycleCommitted &&
                  !beforeEmpty.id.isEmpty() &&
                  afterEmpty.improvementCycles == beforeEmpty.improvementCycles &&
                  afterEmpty.improvementNotes == beforeEmpty.improvementNotes &&
                  afterEmpty.updatedAtMs == beforeEmpty.updatedAtMs,
              QStringLiteral("a successful empty teammate run does not persist an improvement cycle or timestamp update"));

        emptyCycleTeammate = afterEmpty;
        emptyCycleTeammate.lastSessionId = 943100;
        const bool changedRunSaved =
            emptyCycleStore.save(&emptyCycleTeammate, &emptyCycleError);
        const bool changedRunBaseCommitted =
            runGitChecked(emptyCycleRepository.path(), {"add", "-A"}) &&
            runGitChecked(emptyCycleRepository.path(),
                          {"commit", "-m", "prepare changed teammate run"});
        AgentSession changedCycleSession = emptyCycleSession;
        changedCycleSession.id = emptyCycleTeammate.lastSessionId;
        changedCycleSession.baseRef = gitOutput(
            emptyCycleRepository.path(), {QStringLiteral("rev-parse"),
                                          QStringLiteral("HEAD")});
        window.testAddAgentSession(changedCycleSession);
        QFile changedEvidence(
            QDir(emptyCycleRepository.path())
                .filePath(QStringLiteral("actual-change.txt")));
        const bool changedEvidenceWritten =
            changedEvidence.open(QIODevice::WriteOnly | QIODevice::Truncate) &&
            changedEvidence.write("substantive evidence\n") > 0;
        changedEvidence.close();
        const forkmesh::teammates::LoadResult beforeChangedCycle =
            emptyCycleStore.load();
        window.testNotifyAgentDone(
            changedCycleSession.id,
            QStringLiteral("Added repository evidence.\nImprovement note: "
                           "Verify the working tree against the captured base."));
        const forkmesh::teammates::LoadResult afterChangedCycle =
            emptyCycleStore.load();
        const forkmesh::teammates::Config beforeChanged =
            beforeChangedCycle.teammates.isEmpty()
                ? forkmesh::teammates::Config{}
                : beforeChangedCycle.teammates.first();
        const forkmesh::teammates::Config afterChanged =
            afterChangedCycle.teammates.isEmpty()
                ? forkmesh::teammates::Config{}
                : afterChangedCycle.teammates.first();
        check(changedRunSaved && changedRunBaseCommitted &&
                  changedEvidenceWritten && !beforeChanged.id.isEmpty() &&
                  afterChanged.improvementCycles ==
                      beforeChanged.improvementCycles + 1 &&
                  afterChanged.improvementNotes.value(0) ==
                      QLatin1String("Verify the working tree against the captured base."),
              QStringLiteral("a successful teammate run with a substantive change records exactly one improvement cycle"));

        window.testRemoveAgentSession(changedCycleSession.id);
        window.testRemoveAgentSession(emptyCycleSession.id);
        window.testRemoveAgentSession(teammateRun.id);
        window.testRemoveAgentSession(allReplyRun.id);
