    // Popularity counts: a shelf that has heard nothing from the relay shows
    // no number at all, rather than a "0 downloads" the relay never reported.
    const bool noStatsBeforeAnyReport = !marketList || marketList
        ->findChildren<QLabel *>(QStringLiteral("marketPackageStats"))
        .isEmpty();
    QHash<QString, QPair<qint64, qint64>> reportedCounts;
    reportedCounts.insert(QStringLiteral("capture"), qMakePair(4210, 3180));
    reportedCounts.insert(QStringLiteral("winamp"), qMakePair(97, 0));
    // A package the relay reported nothing for stays without a line.
    window.testSetPackageInstallCounts(reportedCounts);
    QApplication::processEvents();
    // refreshMarketPage() retires the old cards with deleteLater(), which
    // processEvents() does not flush; without this the retired cards are still
    // children and every later findChildren() count sees them twice.
    QApplication::sendPostedEvents(nullptr, QEvent::DeferredDelete);
    QHash<QString, QString> statsByPackage;
    const QList<QLabel *> marketStats = marketList
        ? marketList->findChildren<QLabel *>(
              QStringLiteral("marketPackageStats"))
        : QList<QLabel *>{};
    for (QLabel *stats : marketStats) {
        statsByPackage.insert(stats->property("packageId").toString(),
                              stats->text());
    }
    check(noStatsBeforeAnyReport && statsByPackage.size() == 2 &&
              statsByPackage.value(QStringLiteral("capture"))
                      .contains(QLocale().toString(qint64(4210))) &&
              statsByPackage.value(QStringLiteral("capture"))
                      .contains(QStringLiteral("downloads")) &&
              statsByPackage.value(QStringLiteral("capture"))
                      .contains(QLocale().toString(qint64(3180))) &&
              statsByPackage.value(QStringLiteral("capture"))
                      .contains(QStringLiteral("installs")) &&
              statsByPackage.contains(QStringLiteral("winamp")) &&
              !statsByPackage.contains(QStringLiteral("ledger")),
          QStringLiteral("Market cards show reported downloads/installs and "
                         "stay silent for packages with no count "
                         "(before=%1, lines=%2, capture=\"%3\")")
              .arg(noStatsBeforeAnyReport)
              .arg(statsByPackage.size())
              .arg(statsByPackage.value(QStringLiteral("capture"))));
