    const QStringList settingsKeysBeforeSessionCache = QSettings().allKeys();
    window.testCacheAccountSession(
        QStringLiteral(" Alice "), forkmesh::ui::kDefaultServerUrl,
        sessionSecret, true, QStringLiteral("desktop-key"));
    window.testCacheAccountSession(
        QStringLiteral("bob"), remoteAccountInstance,
        QStringLiteral("v2.remote.window-secret"), false, QString());
    check(window.testAccountSessionCacheSize() == 2 &&
              window.testCachedAccountSession(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl) ==
                  sessionSecret &&
              window.testCachedAccountSession(
                  QStringLiteral("alice"), remoteAccountInstance).isEmpty(),
          QStringLiteral("the avatar switcher keeps independent in-memory "
                         "sessions per account and exact instance"));
    check(window.testCachedAccountSessionMaySendTo(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl,
                  QUrl(QStringLiteral(
                      "https://app.forkmesh.com/api/accounts/profile"))) &&
              !window.testCachedAccountSessionMaySendTo(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl,
                  QUrl(QStringLiteral(
                      "https://relay.example.test/api/accounts/profile"))) &&
              !window.testCachedAccountSessionMaySendTo(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl,
                  QUrl(QStringLiteral(
                      "http://app.forkmesh.com/api/accounts/profile"))),
          QStringLiteral("the avatar switcher never sends a cached bearer to "
                         "another origin or a downgraded transport"));
    check(window.testCachedAccountSessionMayRestoreDesktop(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl,
                  QStringLiteral("desktop-key"),
                  QStringLiteral("desktop-key")) &&
              !window.testCachedAccountSessionMayRestoreDesktop(
                  QStringLiteral("alice"), forkmesh::ui::kDefaultServerUrl,
                  QStringLiteral("desktop-key"),
                  QStringLiteral("other-key")) &&
              !window.testCachedAccountSessionMayRestoreDesktop(
                  QStringLiteral("bob"), remoteAccountInstance,
                  QStringLiteral("desktop-key"),
                  QStringLiteral("desktop-key")),
          QStringLiteral("quick switching restores signing only after the "
                         "same local key is revalidated"));
    bool sessionReachedSettings =
        QSettings().allKeys() != settingsKeysBeforeSessionCache;
    for (const QString &key : QSettings().allKeys()) {
        const QVariant value = QSettings().value(key);
        sessionReachedSettings =
            sessionReachedSettings || value.toString().contains(sessionSecret) ||
            value.toByteArray().contains(sessionSecret.toUtf8());
    }
    check(!sessionReachedSettings,
          QStringLiteral("quick-switch bearer tokens never enter QSettings"));
    window.testClearAccountSessionCache();
    check(window.testAccountSessionCacheSize() == 0,
          QStringLiteral("application teardown clears quick-switch sessions"));

    // adhoc #115: startup has resolved now (the bypass marks it done) and this
    // node has no user account, so the pill appears — it is the only way in that
    // the retired setup screen left behind.
    window.testRefreshSignInButton();
    check(window.testSignInButtonVisible(),
          QStringLiteral("the sign-in pill offers a way in once no account is found"));
    check(!window.testUsersNavButtonVisible(),
          QStringLiteral("the Users rail destination is hidden from non-admins"));
    window.testShowUsersSection();
